verifier_output:
st int h = (p-1)/2;
    cv a[32], b[32];
    cv x0 = v[0];
    vf s0r = x0.re, s0i = x0.im;
    for (int n = 1; n <= h; n++) {
        a[n].re = v[n].re + v[p-n].re; a[n].im = v[n].im + v[p-n].im;
        b[n].re = v[n].re - v[p-n].re; b[n].im = v[n].im - v[p-n].im;
        s0r += a[n].re; s0i += a[n].im;
    }
    v[0].re = s0r; v[0].im = s0i;
    int k = 1;
#define KB 4
    for (; k + KB - 1 <= h; k += KB) {
        vf cr[KB], ci[KB], sr[KB], si[KB];
        for (int q = 0; q < KB; q++) { cr[q] = x0.re; ci[q] = x0.im; sr[q] = (vf){}; si[q] = (vf){}; }
        for (int n = 1; n <= h; n++) {
            vf ar = a[n].re, ai = a[n].im, br = b[n].re, bi = b[n].im;
            for (int q = 0; q < KB; q++) {
                float c = ct[(k+q)*h + n-1], s = st[(k+q)*h + n-1];
                cr[q] += ar * c; ci[q] += ai * c;
                sr[q] += br * s; si[q] += bi * s;
            }
        }
        for (int q = 0; q < KB; q++) {
            int kk = k + q;
            v[kk].re = cr[q] + si[q]; v[kk].im = ci[q] - sr[q];
            v[p-kk].re = cr[q] - si[q]; v[p-kk].im = ci[q] + sr[q];
        }
    }
    for (; k <= h; k++) {
        vf cr = x0.re, ci = x0.im, sr = (vf){}, si = (vf){};
        for (int n = 1; n <= h; n++) {
            float c = ct[k*h + n-1], s = st[k*h + n-1];
            cr += a[n].re * c; ci += a[n].im * c;
            sr += b[n].re * s; si += b[n].im * s;
        }
        v[k].re = cr + si; v[k].im = ci - sr;
        v[p-k].re = cr - si; v[p-k].im = ci + sr;
    }
