static inline __attribute__((always_inline)) void stage_body(const cv *restrict in, cv *restrict out, int N, int p, int Ns,
        const float *twr, const float *twi, const float *ct, const float *st, postctx *pc)
{
    const int Np = N / p;
    cv v[64];
    for (int j = 0; j < Np; j++) {
        int k = j % Ns;
        for (int r = 0; r < p; r++) v[r] = in[j + r*Np];
        if (Ns > 1) {
            const float *wr = twr + k*(p-1) - 1, *wi = twi + k*(p-1) - 1;
            for (int r = 1; r < p; r++) {
                vf xr = v[r].re, xi = v[r].im;
                float c = wr[r], s = wi[r];
                v[r].re = xr*c - xi*s; v[r].im = xr*s + xi*c;
            }
        }
        if (p == 2) {
            cv t0 = v[0], t1 = v[1];
            v[0].re = t0.re + t1.re; v[0].im = t0.im + t1.im;
            v[1].re = t0.re - t1.re; v[1].im = t0.im - t1.im;
        } else {
            bfly_odd(v, p, ct, st);
        }
        int base = (j / Ns) * Ns * p + k;
        for (int r = 0; r < p; r++) out[base + r*Ns] = v[r];
        if (pc) post_tick(pc, p);
    }
}

