/* rows r0..r0+nr-1 of X (N x N f64) -> A[q], lanes = rows. stage: >= 32*lds floats scratch (aligned) */
static inline void load_rows_staged(cv *A, float *stage, const double *X, int N, int lds, int r0, int nr)
{
    const int nfull = N & ~15;
    for (int i = 0; i < 32; i++) {
        float *d = stage + (size_t)i*lds;
        if (i < nr) {
            const double *src = X + (size_t)(r0+i)*N;
            int c = 0;
#ifdef NTA
            for (; c < nfull; c += 16) {
                _mm_prefetch((const char*)(src + c + NTA), _MM_HINT_NTA);
                _mm_prefetch((const char*)(src + c + NTA + 8), _MM_HINT_NTA);
                *(vf*)(d + c) = __builtin_convertvector(*(const vd16u*)(src + c), vf);
            }
#else
            for (; c < nfull; c += 16) *(vf*)(d + c) = __builtin_convertvector(*(const vd16u*)(src + c), vf);
#endif
            if (c < N) { vf t = (vf){}; for (int j = 0; c + j < N; j++) t[j] = (float)src[c+j]; *(vf*)(d + c) = t; }
        } else {
            for (int c = 0; c < lds; c += 16) *(vf*)(d + c) = (vf){};
        }
    }
    for (int cb = 0; cb < N; cb += 16) {
        int ncb = N - cb; if (ncb > 16) ncb = 16;
        vf R[16], S[16];
        for (int i = 0; i < 16; i++) { R[i] = *(vf*)(stage + (size_t)i*lds + cb); S[i] = *(vf*)(stage + (size_t)(16+i)*lds + cb); }
        tr16(R); tr16(S);
        for (int j = 0; j < ncb; j++) { int q = giperm[cb+j]; float sg = gsign[q]; A[q].re = R[j]*sg; A[q].im = S[j]*sg; }
    }
}


struct postctx {
    int pass, N, nunits, next;
    long tick, every;
    const cv *Z;
    float *W, *Y;
    int ldy, r0, nr, c0;
};

static void post_unit(postctx *pc)
{
    const int P = 2*VL;
    const int N = pc->N;
    const cv *Z = pc->Z;
    int rb = pc->next * 16;
    pc->next++;
    if (pc->pass == 1) {
        vf da[16], db[16];
        for (int i = 0; i < 16; i++) {
            int row = rb + i;
            if (row < N) {
                int k = N - 1 - row;
                int kk = (k == 0) ? 0 : N - k;
                cv z = Z[k], zn = Z[kk];
                float c = gpc[k], s = gps[k];
                da[i] = (z.re + zn.re) * c + (z.im - zn.im) * s;
                db[i] = (z.im + zn.im) * c + (zn.re - z.re) * s;
            } else { da[i] = (vf){}; db[i] = (vf){}; }
        }
        tr16(da); tr16(db);
        float *wb = pc->W + (size_t)(rb >> 5)*N*P + (rb & 31);
        int nr = pc->nr, r0 = pc->r0;
        int na = nr < VL ? nr : VL; int nb = nr - VL;
        for (int j = 0; j < na; j++) _mm512_stream_ps(wb + (size_t)(r0+j)*P, (__m512)da[j]);
        for (int j = 0; j < nb; j++) _mm512_stream_ps(wb + (size_t)(r0+VL+j)*P, (__m512)db[j]);
    } else {
        int re = rb + 16; if (re > N) re = N;
        for (int row = rb; row < re; row++) {
            int k = N - 1 - row;
            int kk = (k == 0) ? 0 : N - k;
            cv z = Z[k], zn = Z[kk];
            float c = gpc[k], s = gps[k];
            vf da = (z.re + zn.re) * c + (z.im - zn.im) * s;
            vf db = (z.im + zn.im) * c + (zn.re - z.re) * s;
            float *dst = pc->Y + (size_t)row*pc->ldy + pc->c0;
            _mm512_stream_ps(dst, (__m512)da); _mm512_stream_ps(dst+VL, (__m512)db);
        }
    }
}

static void post_tick(postctx *pc, int w)
{
    if (pc->next >= pc->nunits) return;
    pc->tick += w;
    while (pc->tick >= pc->every && pc->next < pc->nunits) { pc->tick -= pc->every; post_unit(pc); }
}

static void post_flush(postctx *pc)
{
    while (pc->next < pc->nunits) post_unit(pc);
}

/* W layout: panel-major  W[p][r][32], p = k2/32, size npan*N*32 floats.
   Y: N x ldy float32 (ldy >= npan*32), 64B aligned */
void dst2d(const double *X, float *W, float *Y, int N, int ldy)
{
    const int P = 2*VL;
    const int npan = (N + P - 1) / P;
    const int lds = (N + 15) & ~15;
    const int nunits = (N + 15) / 16;
    long every = (3L * N) / nunits; if (every < 1) every = 1;
#ifdef EVERYDIV
    every = every * EVERYDIV / 8;
#endif
    #pragma omp parallel
    {
        ensure_scratch(N);
        cv *bufs[3] = {tA, tB, tC};
        int zi = -1;
        postctx pc; pc.N = N; pc.nunits = nunits; pc.every = every; pc.W = W; pc.Y = Y; pc.ldy = ldy;
        int have = 0;
        #pragma omp for schedule(dynamic,1) nowait
        for (int pi = 0; pi < npan; pi++) {
            int r0 = pi*P; int nr = N - r0; if (nr > P) nr = P;
            int a, b;
            if (zi == 0) { a = 1; b = 2; } else if (zi == 1) { a = 0; b = 2; } else { a = 0; b = 1; }
            cv *A = bufs[a], *B = bufs[b];
            load_rows_staged(A, (float*)B, X, N, lds, r0, nr);
            postctx *pp = 0;
            if (have) { pp = &pc; }
            cv *Z = gskip ? A : fft_panel(A, B, N, pp);
            if (have) post_flush(&pc);
            pc.pass = 1; pc.Z = Z; pc.r0 = r0; pc.nr = nr; pc.next = 0; pc.tick = 0;
            have = 1;
            zi = (Z == bufs[0]) ? 0 : (Z == bufs[1] ? 1 : 2);
        }
        if (have) post_flush(&pc);
        #pragma omp barrier
        have = 0;
        #pragma omp for schedule(dynamic,1) nowait
        for (int pi = 0; pi < npan; pi++) {
            int c0 = pi*P;
            int a, b;
            if (zi == 0) { a = 1; b = 2; } else if (zi == 1) { a = 0; b = 2; } else { a = 0; b = 1; }
            cv *A = bufs[a], *B = bufs[b];
            const float *wp = W + (size_t)pi*N*P;
            for (int r = 0; r < N; r++) {
                int q = giperm[r]; float sg = gsign[q];
                A[q].re = *(const vf*)(wp + (size_t)r*P) * sg;
                A[q].im = *(const vf*)(wp + (size_t)r*P + VL) * sg;
            }
            postctx *pp = have ? &pc : 0;
            cv *Z = gskip ? A : fft_panel(A, B, N, pp);
            if (have) post_flush(&pc);
            pc.pass = 2; pc.Z = Z; pc.c0 = c0; pc.next = 0; pc.tick = 0;
            have = 1;
            zi = (Z == bufs[0]) ? 0 : (Z == bufs[1] ? 1 : 2);
        }
        if (have) post_flush(&pc);
    }
}
