/* run FFT stages, data in A; returns pointer to result */
static cv *fft_panel(cv *A, cv *B, int N, postctx *pc)
{
    cv *in = A, *out = B;
    int Ns = 1;
    for (int i = 0; i < gnf; i++) {
        run_stage(in, out, N, gfac[i], Ns, gtwr[i], gtwi[i], gct[i], gst[i], pc);
        Ns *= gfac[i];
        cv *t = in; in = out; out = t;
    }
    return in;
}


