static inline void tr16(vf *R)
{
#ifdef __AVX512F__
    __m512 r[16], t[16];
    for (int i = 0; i < 16; i++) r[i] = (__m512)R[i];
    for (int i = 0; i < 8; i++) { t[2*i] = _mm512_unpacklo_ps(r[2*i], r[2*i+1]); t[2*i+1] = _mm512_unpackhi_ps(r[2*i], r[2*i+1]); }
#define UPD(x,y,f) _mm512_castpd_ps(f(_mm512_castps_pd(x), _mm512_castps_pd(y)))
    for (int i = 0; i < 4; i++) {
        r[4*i]   = UPD(t[4*i],   t[4*i+2], _mm512_unpacklo_pd);
        r[4*i+1] = UPD(t[4*i],   t[4*i+2], _mm512_unpackhi_pd);
        r[4*i+2] = UPD(t[4*i+1], t[4*i+3], _mm512_unpacklo_pd);
        r[4*i+3] = UPD(t[4*i+1], t[4*i+3], _mm512_unpackhi_pd);
    }
    for (int i = 0; i < 4; i++) {
        t[i]    = _mm512_shuffle_f32x4(r[i],   r[i+4],  0x88);
        t[i+4]  = _mm512_shuffle_f32x4(r[i],   r[i+4],  0xdd);
        t[i+8]  = _mm512_shuffle_f32x4(r[i+8], r[i+12], 0x88);
        t[i+12] = _mm512_shuffle_f32x4(r[i+8], r[i+12], 0xdd);
    }
    for (int i = 0; i < 8; i++) {
        R[i]   = (vf)_mm512_shuffle_f32x4(t[i], t[i+8], 0x88);
        R[i+8] = (vf)_mm512_shuffle_f32x4(t[i], t[i+8], 0xdd);
    }
#else
    float tmp[16][16];
    for (int i = 0; i < 16; i++) for (int j = 0; j < 16; j++) tmp[j][i] = R[i][j];
    for (int i = 0; i < 16; i++) for (int j = 0; j < 16; j++) R[i][j] = tmp[i][j];
#endif
}

