/* load panel from rows of src (row stride ld), cols c0..c0+nc-1, permuted by iperm */
static inline void load_panel_f64(cv *A, const double *X, int N, int ld, int c0, int nc)
{
    if (nc == 2*VL) {
        for (int r = 0; r < N; r++) {
            if (r + PD < N) {
                const char *pf = (const char*)(X + (size_t)(r+PD)*ld + c0);
                __builtin_prefetch(pf); __builtin_prefetch(pf+64); __builtin_prefetch(pf+128);
                __builtin_prefetch(pf+192); __builtin_prefetch(pf+255);
            }
            const double *src = X + (size_t)r*ld + c0;
            int q = giperm[r]; float sg = gsign[q];
            for (int j = 0; j < VL; j++) { A[q].re[j] = sg*(float)src[j]; A[q].im[j] = sg*(float)src[VL+j]; }
        }
    } else {
        for (int r = 0; r < N; r++) {
            const double *src = X + (size_t)r*ld + c0;
            int q = giperm[r]; float sg = gsign[q];
            for (int j = 0; j < VL; j++) {
                A[q].re[j] = (j < nc) ? sg*(float)src[j] : 0.0f;
                A[q].im[j] = (VL+j < nc) ? sg*(float)src[VL+j] : 0.0f;
            }
        }
    }
}


