int setup(int N, const int *order, int norder)
{
    /* order: factor list provided by caller (product must be N) */
    int prod = 1;
    for (int i = 0; i < norder; i++) {
        int ok = 0; for (unsigned j = 0; j < sizeof(okp)/sizeof(int); j++) if (okp[j] == order[i]) ok = 1;
        if (!ok) return 0;
        prod *= order[i];
    }
    if (prod != N || norder > MAXF) return 0;
    gN = N; gnf = norder;
    int Ns = 1;
    for (int i = 0; i < norder; i++) {
        int p = order[i]; gfac[i] = p;
        int h = (p-1)/2; if (h < 1) h = 1;
        gtwr[i] = (float*)malloc(sizeof(float)*Ns*(p-1) + 64);
        gtwi[i] = (float*)malloc(sizeof(float)*Ns*(p-1) + 64);
        for (int k = 0; k < Ns; k++) for (int r = 1; r < p; r++) {
            double ang = -2.0*M_PI*(double)r*(double)k/((double)Ns*p);
            gtwr[i][k*(p-1)+r-1] = (float)cos(ang);
            gtwi[i][k*(p-1)+r-1] = (float)sin(ang);
        }
        gct[i] = (float*)malloc(sizeof(float)*(h+1)*h + 64);
        gst[i] = (float*)malloc(sizeof(float)*(h+1)*h + 64);
        for (int k = 1; k <= h; k++) for (int n = 1; n <= h; n++) {
            double th = 2.0*M_PI*(double)((long)n*k % p)/p;
            gct[i][k*h+n-1] = (float)cos(th);
            gst[i][k*h+n-1] = (float)sin(th);
        }
        Ns *= p;
    }
    gpc = (float*)malloc(sizeof(float)*N); gps = (float*)malloc(sizeof(float)*N);
    for (int k = 0; k < N; k++) { gpc[k] = (float)cos(M_PI*k/(2.0*N)); gps[k] = (float)sin(M_PI*k/(2.0*N)); }
    gperm = (int*)malloc(sizeof(int)*N); gsign = (float*)malloc(sizeof(float)*N);
    int half = (N+1)/2;
    for (int q = 0; q < N; q++) {
        if (q < half) { gperm[q] = 2*q; gsign[q] = 1.0f; }
        else { int m = N-1-q; gperm[q] = 2*m+1; gsign[q] = -1.0f; }
    }
    giperm = (int*)malloc(sizeof(int)*N);
    for (int q = 0; q < N; q++) giperm[gperm[q]] = q;
    return 1;
}

