    for (int i = 0; i < 4; i++) {
        t[i]    = _mm512_shuffle_f32x4(r[i],   r[i+4],  0x88);
        t[i+4]  = _mm512_shuffle_f32x4(r[i],   r[i+4],  0xdd);
        t[i+8]  = _mm512_shuffle_f32x4(r[i+8], r[i+12], 0x88);
        t[i+12] = _mm512_shuffle_f32x4(r[i+8], r[i+12], 0xdd);
    }
    for (int i = 0; i < 8; i++) {
        R[i]   = (vf)_mm512_shuffle_f32x4(t[i], t[i+8], 0x88);
        R[i+8] = (vf)_mm512_shuffle_f32x4(t[i], t[i+8], 0xdd);
    }
#else
    float tmp[16][16];
    for (int i = 0; i < 16; i++) for (int j = 0; j < 16; j++) tmp[j][i] = R[i][j];
    for (int i = 0; i < 16; i++) for (int j = 0; j < 16; j++) R[i][j] = tmp[i][j];
