    def _alloc():
        buf = np.empty(N * 2304 + 32, np.float32)
        off = (-(buf.ctypes.data // 4)) % 16
        return buf[off:off + N * 2304].reshape(N, 2304)

    def solve(self, problem, **kwargs):
        x = problem
        if (self.lib is not None and isinstance(x, np.ndarray) and x.shape == (N, N)
                and x.dtype == np.float64):
            if not x.flags.c_contiguous:
                x = np.ascontiguousarray(x)
            U = self._alloc()
            self.lib.dst2d(x.ctypes.data, self.T.ctypes.data, U.ctypes.data, self.nt)
            return U[:, :N]
        x = np.asarray(x, dtype=np.float64)
        return scipy.fft.dstn(x, type=2, workers=self.nt)
