/* ---- complex DFT7 ---- */
#define C11 0.6234898018587336f
#define C12 -0.22252093395631434f
#define C13 -0.900968867902419f
#define C22 -0.9009688679024191f
#define C23 0.6234898018587334f
#define C33 -0.2225209339563141f
#define S11 0.7818314824680298f
#define S12 0.9749279121818236f
#define S13 0.43388373911755823f
#define S22 -0.433883739117558f
#define S23 -0.7818314824680299f
#define S33 0.9749279121818237f

static inline __attribute__((always_inline)) void dft7(const v16* zr, const v16* zi, v16* yr, v16* yi) {
    v16 s1r = zr[1]+zr[6], s1i = zi[1]+zi[6], t1r = zr[1]-zr[6], t1i = zi[1]-zi[6];
    v16 s2r = zr[2]+zr[5], s2i = zi[2]+zi[5], t2r = zr[2]-zr[5], t2i = zi[2]-zi[5];
    v16 s3r = zr[3]+zr[4], s3i = zi[3]+zi[4], t3r = zr[3]-zr[4], t3i = zi[3]-zi[4];
    v16 z0r = zr[0], z0i = zi[0];
    yr[0] = z0r + s1r + s2r + s3r; yi[0] = z0i + s1i + s2i + s3i;
    /* c(j,k)=cos(2pi jk/7): (1,1)=C11,(2,1)=C12,(3,1)=C13; (1,2)=C12,(2,2)=C22,(3,2)=C23; (1,3)=C13,(2,3)=C23,(3,3)=C33 */
    v16 A1r = z0r + C11*s1r + C12*s2r + C13*s3r, A1i = z0i + C11*s1i + C12*s2i + C13*s3i;
    v16 B1r = S11*t1r + S12*t2r + S13*t3r,       B1i = S11*t1i + S12*t2i + S13*t3i;
    v16 A2r = z0r + C12*s1r + C22*s2r + C23*s3r, A2i = z0i + C12*s1i + C22*s2i + C23*s3i;
    v16 B2r = S12*t1r + S22*t2r + S23*t3r,       B2i = S12*t1i + S22*t2i + S23*t3i;
    v16 A3r = z0r + C13*s1r + C23*s2r + C33*s3r, A3i = z0i + C13*s1i + C23*s2i + C33*s3i;
    v16 B3r = S13*t1r + S23*t2r + S33*t3r,       B3i = S13*t1i + S23*t2i + S33*t3i;
    yr[1] = A1r + B1i; yi[1] = A1i - B1r; yr[6] = A1r - B1i; yi[6] = A1i + B1r;
    yr[2] = A2r + B2i; yi[2] = A2i - B2r; yr[5] = A2r - B2i; yi[5] = A2i + B2r;
    yr[3] = A3r + B3i; yi[3] = A3i - B3r; yr[4] = A3r - B3i; yi[4] = A3i + B3r;
}

/* ---- stage B: 49-point complex DFT along n2 for each k1 (in place) ---- */
static void stageB(v16* restrict Zr, v16* restrict Zi) {
    for (int k1 = 0; k1 < K1H; k1++) {
        v16* Pr = Zr + k1*N2; v16* Pi = Zi + k1*N2;
        v16 Ur[7][7], Ui[7][7];
        for (int r = 0; r < 7; r++) {
            v16 zr[7], zi[7], yr[7], yi[7];
            for (int m = 0; m < 7; m++) { zr[m] = Pr[7*m + r]; zi[m] = Pi[7*m + r]; }
            dft7(zr, zi, yr, yi);
            if (r == 0) {
                for (int k = 0; k < 7; k++) { Ur[k][0] = yr[k]; Ui[k][0] = yi[k]; }
            } else {
                Ur[0][r] = yr[0]; Ui[0][r] = yi[0];
                for (int k = 1; k < 7; k++) {
                    float wr = g_twr[r][k], wi = g_twi[r][k];
                    Ur[k][r] = yr[k]*wr - yi[k]*wi;
                    Ui[k][r] = yr[k]*wi + yi[k]*wr;
                }
            }
        }
        for (int k = 0; k < 7; k++) {
            v16 yr[7], yi[7];
            dft7(Ur[k], Ui[k], yr, yi);
            for (int l = 0; l < 7; l++) { Pr[k + 7*l] = yr[l]; Pi[k + 7*l] = yi[l]; }
        }
    }
}

