struct Pool {
  std::vector<std::thread> th; std::mutex mu; std::condition_variable cv, cvd;
  std::function<void(int)> job; long gen=0; int pending=0; bool stop=false; int n=1;
  void start(int nt) {
    n = nt;
    for (int id=1; id<nt; ++id) th.emplace_back([this,id]{
      long seen=0;
      for(;;){
        std::unique_lock<std::mutex> lk(mu);
        cv.wait(lk,[&]{return stop||gen!=seen;});
        if (stop) return;
        seen=gen; auto f=job; lk.unlock();
        f(id);
        lk.lock(); if(--pending==0) cvd.notify_all();
      }});
  }
  void run(const std::function<void(int)>& f) {
    if (n==1) { f(0); return; }
    { std::lock_guard<std::mutex> lk(mu); job=f; pending=n-1; ++gen; }
    cv.notify_all();
    f(0);
    std::unique_lock<std::mutex> lk(mu); cvd.wait(lk,[&]{return pending==0;});
  }
};
