// row pass: transform along axis 1. Input rows from `in` (double or float), output to `out` (float)
static inline void load8(const float* p, __m256& r) { r=_mm256_loadu_ps(p); }
static inline void load8(const double* p, __m256& r) {
  __m128 lo=_mm256_cvtpd_ps(_mm256_loadu_pd(p)), hi=_mm256_cvtpd_ps(_mm256_loadu_pd(p+4));
  r=_mm256_insertf128_ps(_mm256_castps128_ps256(lo), hi, 1);
}
template<typename TI>
static void row_pass_t(const TI* in, float* out, int nt) {
  const int ngroups = (N + 7)/8;
  std::atomic<int> next(0);
  pool->run([&](int id){
    Work& w = *works[id]; V* xb = xbufs[id]; V* yb = ybufs[id]; float* dummy = dummies[id];
    static thread_local TI* dummy_in = nullptr;
    if (!dummy_in) { dummy_in = (TI*)aligned_alloc(64, sizeof(TI)*(N+64)); memset(dummy_in,0,sizeof(TI)*(N+64)); }
    for(;;) {
      int g = next.fetch_add(1); if (g>=ngroups) break;
      int r0 = g*8;
      const TI* rin[8]; float* rows[8];
      for (int j=0;j<8;++j) { rin[j] = (r0+j<N) ? in + (size_t)(r0+j)*N : dummy_in; rows[j] = (r0+j<N) ? out + (size_t)(r0+j)*N : dummy; }
      int i=0;
      for (; i+8<=N; i+=8) {
        __m256 r[8];
        for (int j=0;j<8;++j) load8(rin[j]+i, r[j]);
        tr8(r);
        for (int t=0;t<8;++t) { __m256 v = (t&1)? _mm256_xor_ps(r[t], _mm256_set1_ps(-0.0f)) : r[t]; _mm256_store_ps((float*)&xb[i+t], v); }
      }
      for (; i<N; ++i) { V a; for (int j=0;j<8;++j) a[j]=(float)rin[j][i]; xb[i] = (i&1)? -a : a; }
      core(xb, w);
      const V* br = &w.Bre[0][0]; const V* bi = &w.Bim[0][0];
      for (int p=0;p<N;++p) { int o=T.oidx[p]; yb[p] = T.oc[p]*br[o] + T.os[p]*bi[o]; }
      i=0;
      for (; i+8<=N; i+=8) {
        __m256 r[8];
        for (int t=0;t<8;++t) r[t]=_mm256_load_ps((const float*)&yb[i+t]);
        tr8(r);
        for (int j=0;j<8;++j) _mm256_storeu_ps(rows[j]+i, r[j]);
      }
      for (; i<N; ++i) { V a=yb[i]; for (int j=0;j<8;++j) rows[j][i]=a[j]; }
    }
  });
}

// column pass in place on float
static void col_pass_f(float* out, int nt) {
  const int GW = GV*8;
  const int ngroups = (N + GW-1)/GW;
  std::atomic<int> next(0);
  pool->run([&](int id){
    Work& w = *works[id]; V* xb = xbufs[id];
    for(;;) {
      int g = next.fetch_add(1); if (g>=ngroups) break;
      int c0 = g*GW; int ncol = std::min(GW, N-c0); int nv = (ncol+7)/8;
      if (ncol==GW) {
        for (int n=0;n<N;++n) {
          const float* src = out + (size_t)n*N + c0;
          if (PFD>0 && n+PFD<N) { const char* pf=(const char*)(src + (size_t)PFD*N); for (int q=0;q<GV*32;q+=64) __builtin_prefetch(pf+q); }
          for (int v=0; v<GV; ++v) { V a = *(const Vu*)(src + v*8); xb[(size_t)v*(N+8) + n] = (n&1) ? -a : a; }
        }
      } else {
        for (int n=0;n<N;++n) for (int v=0; v<nv; ++v) {
          V a={}; for (int l=0;l<8 && v*8+l<ncol;++l) a[l]=out[(size_t)n*N+c0+v*8+l];
          xb[(size_t)v*(N+8)+n] = (n&1)? -a : a;
        }
      }
      for (int v=0; v<nv; ++v) {
        core(xb + (size_t)v*(N+8), w);
        const V* br = &w.Bre[0][0]; const V* bi = &w.Bim[0][0];
        V* yb = xb + (size_t)v*(N+8);
        for (int p=0;p<N;++p) { int o=T.oidx[p]; yb[p] = T.oc[p]*br[o] + T.os[p]*bi[o]; }
