      } else {
        for (int p=0;p<N;++p) for (int v=0; v<nv; ++v) { V y = xb[(size_t)v*(N+8)+p]; for (int l=0;l<8 && v*8+l<ncol;++l) out[(size_t)p*N+c0+v*8+l]=y[l]; }
      }
    }
