static inline void stageC_range(const cjob_t* job, int b0, int b1);
static void stageA(const v16* restrict tmp, v16* restrict Zr, v16* restrict Zi, const char* const* pfr, int pfL, const cjob_t* job) {
    int pf_total = pfr ? 16*pfL : 0;
    int pf_per = (pf_total + N2 - 1) / N2;
    int pf_row = 0, pf_line = 0, pf_done = 0;
    for (int n2 = 0; n2 < N2; n2++) {
#if defined(PFHINT) && defined(__AVX512F__)
        { int lim = pf_done + pf_per; if (lim > pf_total) lim = pf_total;
          for (; pf_done < lim; pf_done++) {
            _mm_prefetch(pfr[pf_row] + (long)pf_line*64, PFHINT);
            if (++pf_line == pfL) { pf_line = 0; pf_row++; }
          } }
#endif
        v16 a[24], d[24];
        v16 x0 = tmp[g_src[n2]];
        for (int n = 1; n <= 23; n++) {
            v16 xa = tmp[g_src[n*N2 + n2]];
            v16 xb = tmp[g_src[(N1-n)*N2 + n2]];
            a[n] = xa + xb; d[n] = xa - xb;
        }
        for (int kt = 0; kt < K1H; kt += 8) {
            v16 R0=x0,R1=x0,R2=x0,R3=x0,R4=x0,R5=x0,R6=x0,R7=x0;
            v16 I0={0},I1={0},I2={0},I3={0},I4={0},I5={0},I6={0},I7={0};
            #pragma GCC unroll 23
            for (int n = 1; n <= 23; n++) {
                v16 an = a[n], dn = d[n];
                R0 += an*g_cA[kt+0][n]; R1 += an*g_cA[kt+1][n]; R2 += an*g_cA[kt+2][n]; R3 += an*g_cA[kt+3][n];
                R4 += an*g_cA[kt+4][n]; R5 += an*g_cA[kt+5][n]; R6 += an*g_cA[kt+6][n]; R7 += an*g_cA[kt+7][n];
                I0 += dn*g_sA[kt+0][n]; I1 += dn*g_sA[kt+1][n]; I2 += dn*g_sA[kt+2][n]; I3 += dn*g_sA[kt+3][n];
                I4 += dn*g_sA[kt+4][n]; I5 += dn*g_sA[kt+5][n]; I6 += dn*g_sA[kt+6][n]; I7 += dn*g_sA[kt+7][n];
            }
            Zr[(kt+0)*N2+n2]=R0; Zr[(kt+1)*N2+n2]=R1; Zr[(kt+2)*N2+n2]=R2; Zr[(kt+3)*N2+n2]=R3;
            Zr[(kt+4)*N2+n2]=R4; Zr[(kt+5)*N2+n2]=R5; Zr[(kt+6)*N2+n2]=R6; Zr[(kt+7)*N2+n2]=R7;
            Zi[(kt+0)*N2+n2]=I0; Zi[(kt+1)*N2+n2]=I1; Zi[(kt+2)*N2+n2]=I2; Zi[(kt+3)*N2+n2]=I3;
            Zi[(kt+4)*N2+n2]=I4; Zi[(kt+5)*N2+n2]=I5; Zi[(kt+6)*N2+n2]=I6; Zi[(kt+7)*N2+n2]=I7;
        }
        if (job) { int cb0 = n2*CPER, cb1 = cb0 + CPER; if (cb1 > g_nb) cb1 = g_nb; if (cb0 < cb1) stageC_range(job, cb0, cb1); }
    }
}

/* ---- complex DFT7 ---- */
#define C11 0.6234898018587336f
#define C12 -0.22252093395631434f
#define C13 -0.900968867902419f
#define C22 -0.9009688679024191f
#define C23 0.6234898018587334f
#define C33 -0.2225209339563141f
#define S11 0.7818314824680298f
#define S12 0.9749279121818236f
#define S13 0.43388373911755823f
#define S22 -0.433883739117558f
#define S23 -0.7818314824680299f
#define S33 0.9749279121818237f

static inline __attribute__((always_inline)) void dft7(const v16* zr, const v16* zi, v16* yr, v16* yi) {
    v16 s1r = zr[1]+zr[6], s1i = zi[1]+zi[6], t1r = zr[1]-zr[6], t1i = zi[1]-zi[6];
    v16 s2r = zr[2]+zr[5], s2i = zi[2]+zi[5], t2r = zr[2]-zr[5], t2i = zi[2]-zi[5];
    v16 s3r = zr[3]+zr[4], s3i = zi[3]+zi[4], t3r = zr[3]-zr[4], t3i = zi[3]-zi[4];
    v16 z0r = zr[0], z0i = zi[0];
    yr[0] = z0r + s1r + s2r + s3r; yi[0] = z0i + s1i + s2i + s3i;
    /* c(j,k)=cos(2pi jk/7): (1,1)=C11,(2,1)=C12,(3,1)=C13; (1,2)=C12,(2,2)=C22,(3,2)=C23; (1,3)=C13,(2,3)=C23,(3,3)=C33 */
    v16 A1r = z0r + C11*s1r + C12*s2r + C13*s3r, A1i = z0i + C11*s1i + C12*s2i + C13*s3i;
    v16 B1r = S11*t1r + S12*t2r + S13*t3r,       B1i = S11*t1i + S12*t2i + S13*t3i;
    v16 A2r = z0r + C12*s1r + C22*s2r + C23*s3r, A2i = z0i + C12*s1i + C22*s2i + C23*s3i;
    v16 B2r = S12*t1r + S22*t2r + S23*t3r,       B2i = S12*t1i + S22*t2i + S23*t3i;
    v16 A3r = z0r + C13*s1r + C23*s2r + C33*s3r, A3i = z0i + C13*s1i + C23*s2i + C33*s3i;
    v16 B3r = S13*t1r + S23*t2r + S33*t3r,       B3i = S13*t1i + S23*t2i + S33*t3i;
    yr[1] = A1r + B1i; yi[1] = A1i - B1r; yr[6] = A1r - B1i; yi[6] = A1i + B1r;
    yr[2] = A2r + B2i; yi[2] = A2i - B2r; yr[5] = A2r - B2i; yi[5] = A2i + B2r;
    yr[3] = A3r + B3i; yi[3] = A3i - B3r; yr[4] = A3r - B3i; yi[4] = A3i + B3r;
}

/* ---- stage B: 49-point complex DFT along n2 for each k1 (in place) ---- */
static void stageB(v16* restrict Zr, v16* restrict Zi) {
    for (int k1 = 0; k1 < K1H; k1++) {
        v16* Pr = Zr + k1*N2; v16* Pi = Zi + k1*N2;
        v16 Ur[7][7], Ui[7][7];
        for (int r = 0; r < 7; r++) {
            v16 zr[7], zi[7], yr[7], yi[7];
            for (int m = 0; m < 7; m++) { zr[m] = Pr[7*m + r]; zi[m] = Pi[7*m + r]; }
            dft7(zr, zi, yr, yi);
            if (r == 0) {
                for (int k = 0; k < 7; k++) { Ur[k][0] = yr[k]; Ui[k][0] = yi[k]; }
            } else {
                Ur[0][r] = yr[0]; Ui[0][r] = yi[0];
                for (int k = 1; k < 7; k++) {
                    float wr = g_twr[r][k], wi = g_twi[r][k];
                    Ur[k][r] = yr[k]*wr - yi[k]*wi;
                    Ui[k][r] = yr[k]*wi + yi[k]*wr;
                }
            }
        }
        for (int k = 0; k < 7; k++) {
            v16 yr[7], yi[7];
            dft7(Ur[k], Ui[k], yr, yi);
            for (int l = 0; l < 7; l++) { Pr[k + 7*l] = yr[l]; Pi[k + 7*l] = yi[l]; }
        }
    }
}

/* ---- stage C: post-twiddle and scatter to dst rows ---- */

static inline void stageC_range(const cjob_t* job, int b0, int b1) {
    const v16* restrict Zr = job->Zr; const v16* restrict Zi = job->Zi;
    float* base = job->dst + job->col0; long dstride = job->dstride;
#ifdef __AVX512F__
    if (job->nt) {
        for (int b = b0; b < b1; b++) {
            int idx = g_bidx[b];
            v16 wr = Zr[idx], wi = Zi[idx];
            float C = g_C[b], S = g_S[b];
            _mm512_stream_ps(base + (long)g_j1[b]*dstride, (__m512)(C*wr + S*wi));
            int j2 = g_j2[b];
            if (j2 >= 0) _mm512_stream_ps(base + (long)j2*dstride, (__m512)(S*wr - C*wi));
        }
        return;
    }
#endif
    for (int b = b0; b < b1; b++) {
        int idx = g_bidx[b];
        v16 wr = Zr[idx], wi = Zi[idx];
        float C = g_C[b], S = g_S[b];
        *(v16u*)(base + (long)g_j1[b]*dstride) = C*wr + S*wi;
        int j2 = g_j2[b];
        if (j2 >= 0) *(v16u*)(base + (long)j2*dstride) = S*wr - C*wi;
    }
}

#define WS_TMP (NN+1)
#define WS_Z (K1H*N2)
#define WS_PER_THREAD (WS_TMP + 4*WS_Z + 16)

long ws_floats_per_thread(void) { return (long)WS_PER_THREAD * LW; }

static void run_pass(int pass, const double* X, long xstride, const float* S, long sstride,
                     float* dst, long dstride, int nt, int tid, int nth, v16* w) {
    const int nblk = (NN + LW - 1) / LW;
    int b_lo = (int)((long)tid * nblk / nth), b_hi = (int)((long)(tid+1) * nblk / nth);
    v16* tmp = w;
    v16* Zr[2]; v16* Zi[2];
    Zr[0] = w + WS_TMP; Zi[0] = Zr[0] + WS_Z; Zr[1] = Zi[0] + WS_Z; Zi[1] = Zr[1] + WS_Z;
    cjob_t job; int have_job = 0; int cur = 0;
    for (int blk = b_lo; blk < b_hi; blk++) {
        int r0 = blk*LW;
        const char* pfr[16]; const char* const* pfp = 0; int pfL = 0;
        if (pass == 1) {
            gather_rows_d(X, xstride, r0, tmp);
            if (blk + 1 < b_hi) { for (int b = 0; b < 16; b++) { int row = r0 + 16 + b; if (row > NN-1) row = NN-1; pfr[b] = (const char*)(X + (long)row*xstride); } pfp = pfr; pfL = (int)((xstride*8 + 63)/64) + 1; }
        } else {
            gather_rows_f(S, sstride, r0, tmp);
            if (blk + 1 < b_hi) { for (int b = 0; b < 16; b++) { int row = r0 + 16 + b; if (row > NN-1) row = NN-1; pfr[b] = (const char*)(S + (long)row*sstride); } pfp = pfr; pfL = (int)((sstride*4 + 63)/64); }
        }
#ifndef PFHINT
        pfp = 0;
#endif
        stageA(tmp, Zr[cur], Zi[cur], pfp, pfL, have_job ? &job : 0);
        stageB(Zr[cur], Zi[cur]);
        job.Zr = Zr[cur]; job.Zi = Zi[cur]; job.dst = dst; job.dstride = dstride; job.col0 = r0; job.nt = nt;
        have_job = 1; cur ^= 1;
    }
    if (have_job) stageC_range(&job, 0, g_nb);
#ifdef __AVX512F__
    if (nt) _mm_sfence();
#endif
}

void dst2d(const double* X, long xstride, float* T, float* Zout, long stride, float* ws, int nthreads, int ntT, int ntY) {
    #pragma omp parallel num_threads(nthreads)
    {
        int tid = omp_get_thread_num();
        int nth = omp_get_num_threads();
        v16* w = (v16*)(ws + (long)tid * WS_PER_THREAD * LW);
