  v16 b1r = S1*d1i + S2*d2i + S3*d3i, b1i = S1*d1r + S2*d2r + S3*d3r;
  v16 a2r = x0r + C2*s1r + C3*s2r + C1*s3r, a2i = x0i + C2*s1i + C3*s2i + C1*s3i;
  v16 b2r = S2*d1i - S3*d2i - S1*d3i, b2i = S2*d1r - S3*d2r - S1*d3r;
  v16 a3r = x0r + C3*s1r + C1*s2r + C2*s3r, a3i = x0i + C3*s1i + C1*s2i + C2*s3i;
  v16 b3r = S3*d1i - S1*d2i + S2*d3i, b3i = S3*d1r - S1*d2r + S2*d3r;
  yr[1] = a1r + b1r; yi[1] = a1i - b1i; yr[6] = a1r - b1r; yi[6] = a1i + b1i;
  yr[2] = a2r + b2r; yi[2] = a2i - b2i; yr[5] = a2r - b2r; yi[5] = a2i + b2i;
  yr[3] = a3r + b3r; yi[3] = a3i - b3i; yr[4] = a3r - b3r; yi[4] = a3i + b3i;
