AI void dft49(v16 * restrict Ar, v16 * restrict Ai, int base) {
  v16 gr[49], gi[49];
  v16 xr[7], xi[7], yr[7], yi[7];
  for (int s = 0; s < 7; s++) {
    for (int r = 0; r < 7; r++) { xr[r] = Ar[base + 7*r + s]; xi[r] = Ai[base + 7*r + s]; }
    dft7(xr, xi, yr, yi);
    for (int u = 0; u < 7; u++) {
      if (s == 0 || u == 0) { gr[s*7+u] = yr[u]; gi[s*7+u] = yi[u]; }
      else {
        float c = TWR[s*7+u], sn = TWI[s*7+u];
        gr[s*7+u] = yr[u]*c + yi[u]*sn; gi[s*7+u] = yi[u]*c - yr[u]*sn;
      }
