  }
  for (int u = 0; u < 7; u++) {
    for (int s = 0; s < 7; s++) { xr[s] = gr[s*7+u]; xi[s] = gi[s*7+u]; }
    dft7(xr, xi, yr, yi);
    for (int v = 0; v < 7; v++) { Ar[base + u + 7*v] = yr[v]; Ai[base + u + 7*v] = yi[v]; }
