  int per = (tot + nit - 1) / nit;
  int q0 = it*per, q1 = q0 + per; if (q1 > tot) q1 = tot;
  if (q0 >= q1) return;
  int r = q0 / pf->lines, l = q0 - r*pf->lines;
  for (int q = q0; q < q1; q++) {
    __builtin_prefetch(pf->base + (size_t)r*pf->rstride + (size_t)l*64, 0, 2);
    if (++l == pf->lines) { l = 0; r++; }
