    v16 ya = c*sr + s*di, yb = c*si - s*dr;
    v16 ya2 = s*sr - c*di, yb2 = s*si + c*dr;
    float *row1 = out + (size_t)(NN-1-m)*NP + c0;
    float *row2 = out + (size_t)(m-1)*NP + c0;
    st16(row1, ya, nt); st16(row1+16, yb, nt);
    st16(row2, ya2, nt); st16(row2+16, yb2, nt);
  }
