int dst_setup(int nt) {
  if (g_work && g_nt >= nt) return 0;
  if (g_work) free(g_work);
  g_work = (float*)aligned_alloc(64, (size_t)nt * 2 * NN * 16 * sizeof(float) + 64);
  if (!g_work) return -1;
  memset(g_work, 0, (size_t)nt * 2 * NN * 16 * sizeof(float));
  g_nt = nt;
  return 0;
}

int dst2d(const double *X, float *T, float *U, int nt) {
  if (!g_work || nt > g_nt) return -1;
  #pragma omp parallel num_threads(nt)
  {
    int tid = omp_get_thread_num();
    v16 *Ar = (v16*)(g_work + (size_t)tid * 2 * NN * 16);
    v16 *Ai = Ar + NN;
    int ntt = omp_get_num_threads();
    int bs = tid*NBLK/ntt, be = (tid+1)*NBLK/ntt;
    for (int b = bs; b < be; b++) block_rows_d(X, T, b, Ar, Ai, b + 1 < be);
#if NT_T
    _mm_sfence();
#endif
    #pragma omp barrier
    for (int b = bs; b < be; b++) block_rows_f(T, U, b, Ar, Ai, b + 1 < be);
    _mm_sfence();
  }
  return 0;
}
