static inline void tr16(__m512 r[16]) {
    __m512 t[16];
    for (int i = 0; i < 8; i++) {
        t[2*i] = _mm512_unpacklo_ps(r[2*i], r[2*i+1]);
        t[2*i+1] = _mm512_unpackhi_ps(r[2*i], r[2*i+1]);
    }
    for (int i = 0; i < 4; i++) {
        r[4*i]   = _mm512_shuffle_ps(t[4*i],   t[4*i+2], 0x44);
        r[4*i+1] = _mm512_shuffle_ps(t[4*i],   t[4*i+2], 0xEE);
        r[4*i+2] = _mm512_shuffle_ps(t[4*i+1], t[4*i+3], 0x44);
        r[4*i+3] = _mm512_shuffle_ps(t[4*i+1], t[4*i+3], 0xEE);
    }
    for (int h = 0; h < 2; h++) {
        int b = 8*h;
        for (int i = 0; i < 4; i++) {
            t[b+i]   = _mm512_shuffle_f32x4(r[b+i], r[b+4+i], 0x88);
            t[b+4+i] = _mm512_shuffle_f32x4(r[b+i], r[b+4+i], 0xdd);
        }
    }
    for (int i = 0; i < 8; i++) {
        r[i]   = _mm512_shuffle_f32x4(t[i], t[8+i], 0x88);
        r[8+i] = _mm512_shuffle_f32x4(t[i], t[8+i], 0xdd);
    }
}

typedef struct {
    const double* X; float* Y; float* O; int pass; volatile int* next;
} job_t;

typedef struct { const double* X; float* Y; float* O; int next1, next2; int arrived; int total; } ctx_t;

static void do_block(const job_t* jb, int blk, v16* tile, v16* Tr, v16* Ti) {
    int r0 = blk * 16;
    if (jb->pass == 1) {
        /* tile[n][l] = sg[n]*sg[r0+l]*X[r0+l][n], transposed read from X (f64) */
        const double* X = jb->X;
        v16 ls = *(const v16u*)(sgn + r0);
        int nl = NN - r0; if (nl > 16) nl = 16;
        for (int nb = 0; nb < NP; nb += 16) {
            __m512 r[16];
            __mmask8 m1 = 0xFF, m2 = 0xFF;
            if (nb + 16 > NN) { int rem = NN - nb; m1 = rem >= 8 ? 0xFF : (1u << rem) - 1; m2 = rem >= 16 ? 0xFF : (rem > 8 ? (1u << (rem - 8)) - 1 : 0); }
            for (int l = 0; l < 16; l++) {
                if (l < nl) {
                    const double* p = X + (size_t)(r0 + l) * NN + nb;
                    __m512d a = _mm512_maskz_loadu_pd(m1, p), b = _mm512_maskz_loadu_pd(m2, p + 8);
                    r[l] = _mm512_insertf32x8(_mm512_castps256_ps512(_mm512_cvtpd_ps(a)), _mm512_cvtpd_ps(b), 1);
                } else r[l] = _mm512_setzero_ps();
            }
            tr16(r);
            for (int i = 0; i < 16; i++) tile[nb + i] = (v16)r[i] * (sgn[nb + i] * ls);
        }
        core(tile, jb->Y, r0, Tr, Ti, NT1);
    } else {
        const float* Y = jb->Y + (size_t)r0 * NP;
        for (int nb = 0; nb < NP; nb += 16) {
            __m512 r[16];
            for (int l = 0; l < 16; l++) r[l] = _mm512_load_ps(Y + (size_t)l * NP + nb);
            tr16(r);
            for (int i = 0; i < 16; i++) tile[nb + i] = (v16)r[i];
        }
        core(tile, jb->O, r0, Tr, Ti, NT2);
    }
}

static void* worker(void* arg) {
    ctx_t* cx = (ctx_t*)arg;
    v16 tile[NP];
    v16 Tr[24 * 49], Ti[24 * 49];
    job_t jb; jb.X = cx->X; jb.Y = cx->Y; jb.O = cx->O;
    jb.pass = 1;
    for (;;) {
        int blk = __atomic_fetch_add(&cx->next1, 1, __ATOMIC_RELAXED);
        if (blk >= NBLK) break;
        do_block(&jb, blk, tile, Tr, Ti);
    }
    _mm_sfence();
    __atomic_fetch_add(&cx->arrived, 1, __ATOMIC_ACQ_REL);
    while (__atomic_load_n(&cx->arrived, __ATOMIC_ACQUIRE) < __atomic_load_n(&cx->total, __ATOMIC_ACQUIRE)) _mm_pause();
    jb.pass = 2;
    for (;;) {
        int blk = __atomic_fetch_add(&cx->next2, 1, __ATOMIC_RELAXED);
        if (blk >= NBLK) break;
        do_block(&jb, blk, tile, Tr, Ti);
    }
    _mm_sfence();
    return 0;
}

#include <unistd.h>
static pthread_mutex_t mu = PTHREAD_MUTEX_INITIALIZER;
static pthread_cond_t cv_start = PTHREAD_COND_INITIALIZER, cv_done = PTHREAD_COND_INITIALIZER;
static int pool_pid = -1, pool_n = 0, ndone = 0;
static unsigned long gen = 0;
static ctx_t* cur = 0;

static void* pool_worker(void* arg) {
    unsigned long my = (unsigned long)(uintptr_t)arg;
    for (;;) {
        pthread_mutex_lock(&mu);
        while (gen == my) pthread_cond_wait(&cv_start, &mu);
        my = gen; ctx_t* cx = cur;
        pthread_mutex_unlock(&mu);
        worker(cx);
        pthread_mutex_lock(&mu);
        if (++ndone >= pool_n) pthread_cond_signal(&cv_done);
        pthread_mutex_unlock(&mu);
    }
    return 0;
}

void dst2(const double* X, float* Y, float* O, int nth) {
    if (nth < 1) nth = 1;
    if (nth > 256) nth = 256;
    int pid = (int)getpid();
    if (pool_pid != pid) {
        /* (re)create pool in this process (fork-safe) */
        pthread_mutex_init(&mu, 0); pthread_cond_init(&cv_start, 0); pthread_cond_init(&cv_done, 0);
        pool_n = 0; ndone = 0;
        pthread_attr_t at; pthread_attr_init(&at); pthread_attr_setstacksize(&at, 4 << 20);
        pthread_attr_setdetachstate(&at, PTHREAD_CREATE_DETACHED);
        for (int i = 1; i < nth; i++) {
            pthread_t t;
            if (pthread_create(&t, &at, pool_worker, (void*)(uintptr_t)gen) == 0) pool_n++;
        }
        pthread_attr_destroy(&at);
        pool_pid = pid;
    }
    ctx_t cx; cx.X = X; cx.Y = Y; cx.O = O; cx.next1 = 0; cx.next2 = 0; cx.arrived = 0;
    cx.total = pool_n + 1;
    pthread_mutex_lock(&mu);
    cur = &cx; ndone = 0; gen++;
