def _make_tables():
    perm = np.empty(N, np.int64)
    h = (N + 1) // 2
    perm[:h] = 2 * np.arange(h)
    perm[h:] = (2 * np.arange((N - 1) // 2) + 1)[::-1]
    n1 = np.arange(N1)[:, None]
    n2 = np.arange(N2)[None, :]
    m = (N2 * n1 + N1 * n2) % N
    idx = np.ascontiguousarray(perm[m].T).astype(np.int32)
    u = pow(N2, -1, N1)
    v = pow(N1, -1, N2)
    k1 = np.arange(N1)[:, None]
    k2 = np.arange(N2)[None, :]
    K = ((N2 * u * k1 + N1 * v * k2) % N)[:24]
    o1 = (N - 1 - K).astype(np.int32)
    o2 = (K - 1).astype(np.int32)
    o2[0] = 0
    th = np.pi * K / (2 * N)
    ph = np.pi * (N - K) / (2 * N)
    cf = np.zeros((24, 49, 4), np.float64)
    cf[:, :, 0] = 2 * np.cos(th)
    cf[:, :, 1] = 2 * np.sin(th)
    cf[:, :, 2] = 2 * np.cos(ph)
    cf[:, :, 3] = -2 * np.sin(ph)
    kk = np.arange(24)[:, None]
    jj = np.arange(24)[None, :]
    C = np.cos(2 * np.pi * kk * jj / N1)
    S = np.sin(2 * np.pi * kk * (jj + 1) / N1)
