    float *blk = buf + qd*Q*V;
    apply_dim(A + h1*H1*H1, H1, blk, tmp, H2*V, V, H2, pf);
    apply_dim(B + h2*H2*H2, H2, tmp, blk, V, H2*V, H1, pf);
