    t[8*h+j]   = _mm512_shuffle_f32x4(r[8*h+j], r[8*h+4+j], 0x88);
    t[8*h+4+j] = _mm512_shuffle_f32x4(r[8*h+j], r[8*h+4+j], 0xdd);
  }
  for (int j = 0; j < 8; j++) {
    r[j]   = _mm512_shuffle_f32x4(t[j], t[8+j], 0x88);
    r[8+j] = _mm512_shuffle_f32x4(t[j], t[8+j], 0xdd);
