        float *o = t2 + j*V;
        for (int gi = 0; gi < 4; gi++) {
          float x0 = sc[gi*4+0]*(float)xr[gi*4+0][j];
          float x1 = sc[gi*4+1]*(float)xr[gi*4+1][j];
