def _small_mats(p, H):
    Mc = np.zeros((H, H)); Ms = np.zeros((H, H))
    for t in range(H):
        for j in range(H):
            if t <= (p-1)//2 and j <= (p-1)//2:
                Mc[t, j] = np.cos(2*np.pi*j*t/p)
            if t <= (p-1)//2 - 1 and j <= (p-1)//2 - 1:
                Ms[t, j] = np.sin(2*np.pi*(j+1)*(t+1)/p)
    return np.stack([Mc, Ms])

def _pidx(h1, h2, j1, j2):
    return ((h1*2+h2)*H1 + j1)*H2 + j2

def _tables():
    a_ = pow(N, -1, 4); b_ = pow(4, -1, N)
    m = np.array([(r + N*((1 - r) * a_ % 4)) % (4*N) for r in range(N)])
    n_of_r = np.where(m < 2*N, (m-1)//2, (4*N - m - 1)//2)
    def nr(r1, r2):
        return int(n_of_r[(P2*(r1 % P1) + P1*(r2 % P2)) % N])
    sgn = (1 - 2*(np.arange(N) % 2)).astype(np.float64)
    gsrc = np.zeros((Q, 4), np.int32); gcoef = np.zeros((Q, 4), np.float32)
    prow = np.full((Q, 4), L, np.int32)
    for u1 in range(H1):
        for u2 in range(H2):
            g = u1*H2 + u2
            src = [nr(u1, u2), nr(u1, -u2), nr(-u1, u2), nr(-u1, -u2)]
            gsrc[g] = src
            f = [1, 0 if u2 == 0 else 1, 0 if u1 == 0 else 1, 0 if (u1 == 0 or u2 == 0) else 1]
            gcoef[g] = [sgn[src[i]]*f[i] for i in range(4)]
            for c in range(4):
                ha, hb = c >> 1, c & 1
                if (ha == 1 and u1 == 0) or (hb == 1 and u2 == 0):
                    continue
                prow[g, c] = _pidx(ha, hb, u1-ha, u2-hb)
    oidx = np.zeros((N, 2), np.int32); ocoef = np.zeros((N, 2), np.float32)
    for k in range(N):
        kk = N-1-k
        t = (b_*kk) % N; phi = (a_*kk) % 4
        t1 = t % P1; t2 = t % P2
        u1 = min(t1, P1-t1); s1 = 1 if t1 <= (P1-1)//2 else -1
        u2 = min(t2, P2-t2); s2 = 1 if t2 <= (P2-1)//2 else -1
        cphi = [1, 0, -1, 0][phi]; sphi = [0, 1, 0, -1][phi]
        if cphi != 0:
            oidx[k, 0] = _pidx(0, 0, u1, u2); ocoef[k, 0] = cphi
            if u1 >= 1 and u2 >= 1:
                oidx[k, 1] = _pidx(1, 1, u1-1, u2-1); ocoef[k, 1] = -cphi*s1*s2
        else:
            if u1 >= 1:
                oidx[k, 0] = _pidx(1, 0, u1-1, u2); ocoef[k, 0] = -sphi*s1
            if u2 >= 1:
                oidx[k, 1] = _pidx(0, 1, u1, u2-1); ocoef[k, 1] = -sphi*s2
    ocoef *= 2.0
    oidx = np.concatenate([oidx, np.zeros((NP-N, 2), np.int32)]); ocoef = np.concatenate([ocoef, np.zeros((NP-N, 2), np.float32)])
    colsign = np.concatenate([sgn, np.zeros(NP-N)]).astype(np.float32)
    A = _small_mats(P1, H1).astype(np.float32)
    B = _small_mats(P2, H2).astype(np.float32)
    return gsrc, gcoef, prow, colsign, oidx, ocoef, A, B

def _build():
    h = hashlib.md5(C_SRC.encode()).hexdigest()[:12]
    d = tempfile.gettempdir()
    so = os.path.join(d, f"dst2_{h}.so")
    if not os.path.exists(so):
        src = os.path.join(d, f"dst2_{h}.c")
        with open(src, "w") as f:
            f.write(C_SRC)
        tmpso = so + f".{os.getpid()}.tmp"
        subprocess.check_call(["gcc", "-O3", "-march=native", "-ffast-math", "-fopenmp", "-shared", "-fPIC",
                               "-o", tmpso, src])
        os.replace(tmpso, so)
    lib = ctypes.CDLL(so)
    lib.run.restype = None
    return lib

class Solver:
    def __init__(self):
        self.fallback = False
        try:
            flags = open('/proc/cpuinfo').read()
            if 'avx512f' not in flags:
                raise RuntimeError('no avx512')
            self.lib = _build()
        except Exception:
            self.fallback = True
            return
        tabs = _tables()
        self.tabs = [np.ascontiguousarray(t) for t in tabs]
        raw = np.zeros((NP // 16) * (L + 1) * 16 + 64, np.float32)
        off = (-raw.ctypes.data % 64) // 4
        self._T1raw = raw
        self.T1 = raw[off:off + (NP // 16) * (L + 1) * 16]
        self.nthreads = len(os.sched_getaffinity(0))
        self.tm = np.zeros(16)
        self._ptrs = [t.ctypes.data for t in self.tabs]
        self.solve(np.random.rand(N, N))

    def solve(self, problem, **kwargs):
        X = np.asarray(problem)
        if self.fallback or X.shape != (N, N):
            import scipy.fft
            return scipy.fft.dstn(X.astype(np.float64), type=2, workers=-1)
        X = np.ascontiguousarray(X, dtype=np.float64)
        raw = np.empty(N * NP + 16, np.float32)
        off = (-raw.ctypes.data % 64) // 4
        Y = raw[off:off + N * NP].reshape(N, NP)
        p = self._ptrs
        self.lib.run(ctypes.c_void_p(X.ctypes.data), ctypes.c_void_p(self.T1.ctypes.data), ctypes.c_void_p(Y.ctypes.data),
                     ctypes.c_void_p(p[0]), ctypes.c_void_p(p[1]), ctypes.c_void_p(p[2]), ctypes.c_void_p(p[3]),
                     ctypes.c_void_p(p[4]), ctypes.c_void_p(p[5]), ctypes.c_void_p(p[6]), ctypes.c_void_p(p[7]),
                     ctypes.c_int(self.nthreads), ctypes.c_void_p(self.tm.ctypes.data))
        return Y[:, :N]
