            c47[k][m] = (float)cos(2 * PI * ((long)m * k % 47) / 47.0);
            s47[k][m] = (float)(-sin(2 * PI * ((long)m * k % 47) / 47.0));
        }
    for (int k = 0; k < 25; k++)
        for (int m = 0; m < 25; m++) {
            c49[k][m] = (float)cos(2 * PI * ((long)m * k % 49) / 49.0);
            s49[k][m] = (float)sin(2 * PI * ((long)m * k % 49) / 49.0);
        }
    static int crt[N1][N2];
    for (int k = 0; k < N; k++) crt[k % 49][k % 47] = k;
    for (int k1 = 0; k1 < N1; k1++)
        for (int k2 = 0; k2 < 24; k2++) {
            int k = crt[k1][k2];
            outA[k1][k2] = N - 1 - k;
            outB[k1][k2] = k - 1;  /* -1 for k==0 */
            double th = PI * k / (2.0 * N);
