    vf u0 = u[0];
    for (int k = 0; k < 24; k += 8) {
        vf a0 = u0, a1 = u0, a2 = u0, a3 = u0, a4 = u0, a5 = u0, a6 = u0, a7 = u0;
        for (int m = 1; m < 24; m++) {
            vf em = e[m];
            a0 += c47[k + 0][m] * em; a1 += c47[k + 1][m] * em;
            a2 += c47[k + 2][m] * em; a3 += c47[k + 3][m] * em;
            a4 += c47[k + 4][m] * em; a5 += c47[k + 5][m] * em;
            a6 += c47[k + 6][m] * em; a7 += c47[k + 7][m] * em;
        }
        wout[k] = a0; wout[k + 1] = a1; wout[k + 2] = a2; wout[k + 3] = a3;
        wout[k + 4] = a4; wout[k + 5] = a5; wout[k + 6] = a6; wout[k + 7] = a7;
    }
    for (int k = 0; k < 24; k += 8) {
        vf z = {0};
        vf a0 = z, a1 = z, a2 = z, a3 = z, a4 = z, a5 = z, a6 = z, a7 = z;
        for (int m = 1; m < 24; m++) {
            vf om = o[m];
            a0 += s47[k + 0][m] * om; a1 += s47[k + 1][m] * om;
            a2 += s47[k + 2][m] * om; a3 += s47[k + 3][m] * om;
            a4 += s47[k + 4][m] * om; a5 += s47[k + 5][m] * om;
            a6 += s47[k + 6][m] * om; a7 += s47[k + 7][m] * om;
        }
        wout[24 + k] = a0; wout[24 + k + 1] = a1; wout[24 + k + 2] = a2; wout[24 + k + 3] = a3;
        wout[24 + k + 4] = a4; wout[24 + k + 5] = a5; wout[24 + k + 6] = a6; wout[24 + k + 7] = a7;
    }
