static inline __attribute__((always_inline)) void st(float* base, long stride, int idx, vf v, int nt) {
    float* p = base + (long)idx * stride;
#ifdef __AVX512F__
    if (nt) { _mm512_stream_ps(p, (__m512)v); return; }
#endif
