}
static inline __attribute__((always_inline)) void emit(float* restrict ob, long os, int nt, int k1, int k2, vf vr, vf vi) {
    float cs = ocs[k1][k2], sn = osn[k1][k2];
    st(ob, os, outA[k1][k2], cs * vr + sn * vi, nt);
    int b = outB[k1][k2];
    if (b >= 0) st(ob, os, b, sn * vr - cs * vi, nt);
}

/* 7x7 Cooley-Tukey 49-point complex DFT stageB (drop-in). n = 7a+b, k = c+7d. */
#define C7_1 0.62348980185873353053f
#define C7_2 -0.22252093395631440429f
#define C7_3 -0.90096886790241912624f
#define S7_1 0.78183148246802980871f
#define S7_2 0.97492791218182360702f
#define S7_3 0.43388373911755812048f
static float tw49r[7][7], tw49i[7][7];
static void init_tw49(void) {
    const double PI = 3.14159265358979323846;
    for (int b = 0; b < 7; b++) for (int c = 0; c < 7; c++) {
        tw49r[b][c] = (float)cos(2 * PI * b * c / 49.0);
        tw49i[b][c] = (float)(-sin(2 * PI * b * c / 49.0));
    }
}
static inline __attribute__((always_inline)) void dft7(const vf* ur, const vf* ui, vf* yr, vf* yi) {
    vf t1r = ur[1] + ur[6], t1i = ui[1] + ui[6], s1r = ur[1] - ur[6], s1i = ui[1] - ui[6];
    vf t2r = ur[2] + ur[5], t2i = ui[2] + ui[5], s2r = ur[2] - ur[5], s2i = ui[2] - ui[5];
    vf t3r = ur[3] + ur[4], t3i = ui[3] + ui[4], s3r = ur[3] - ur[4], s3i = ui[3] - ui[4];
    vf u0r = ur[0], u0i = ui[0];
    yr[0] = u0r + t1r + t2r + t3r; yi[0] = u0i + t1i + t2i + t3i;
    vf R1r = u0r + C7_1 * t1r + C7_2 * t2r + C7_3 * t3r, R1i = u0i + C7_1 * t1i + C7_2 * t2i + C7_3 * t3i;
    vf R2r = u0r + C7_2 * t1r + C7_3 * t2r + C7_1 * t3r, R2i = u0i + C7_2 * t1i + C7_3 * t2i + C7_1 * t3i;
    vf R3r = u0r + C7_3 * t1r + C7_1 * t2r + C7_2 * t3r, R3i = u0i + C7_3 * t1i + C7_1 * t2i + C7_2 * t3i;
    vf I1r = S7_1 * s1r + S7_2 * s2r + S7_3 * s3r, I1i = S7_1 * s1i + S7_2 * s2i + S7_3 * s3i;
    vf I2r = S7_2 * s1r - S7_3 * s2r - S7_1 * s3r, I2i = S7_2 * s1i - S7_3 * s2i - S7_1 * s3i;
    vf I3r = S7_3 * s1r - S7_1 * s2r + S7_2 * s3r, I3i = S7_3 * s1i - S7_1 * s2i + S7_2 * s3i;
    /* X[k] = R - i I ; X[7-k] = R + i I */
    yr[1] = R1r + I1i; yi[1] = R1i - I1r; yr[6] = R1r - I1i; yi[6] = R1i + I1r;
    yr[2] = R2r + I2i; yi[2] = R2i - I2r; yr[5] = R2r - I2i; yi[5] = R2i + I2r;
    yr[3] = R3r + I3i; yi[3] = R3i - I3r; yr[4] = R3r - I3i; yi[4] = R3i + I3r;
}
static inline __attribute__((always_inline)) void stageB(const vf* restrict wbuf, float* restrict ob, long os, int nt) {
    vf yr[49], yi[49];
    for (int k2 = 0; k2 < 24; k2++) {
        const vf* A = wbuf + k2;
        const vf* Bv = wbuf + 24 + k2;
        for (int b = 0; b < 7; b++) {
            vf ur[7], ui[7];
            for (int a = 0; a < 7; a++) { ur[a] = A[(7 * a + b) * 48]; ui[a] = Bv[(7 * a + b) * 48]; }
            dft7(ur, ui, yr + 7 * b, yi + 7 * b);
        }
        for (int b = 1; b < 7; b++)
            for (int c = 1; c < 7; c++) {
                float wr = tw49r[b][c], wi = tw49i[b][c];
                vf r = yr[7 * b + c], i = yi[7 * b + c];
                yr[7 * b + c] = r * wr - i * wi;
                yi[7 * b + c] = r * wi + i * wr;
            }
        for (int c = 0; c < 7; c++) {
            vf ur[7], ui[7], zr[7], zi[7];
            for (int b = 0; b < 7; b++) { ur[b] = yr[7 * b + c]; ui[b] = yi[7 * b + c]; }
            dft7(ur, ui, zr, zi);
            for (int d = 0; d < 7; d++) {
                int k = c + 7 * d;
                if (k2 == 0 && k > 24) continue;
                emit(ob, os, nt, k, k2, zr[d], zi[d]);
            }
        }
    }
}

