/* load 16 rows (row stride ld elements) starting at src, transpose into T[c][16] for c < ncols */
static void load_T_d(const double* src, long ld, float* T, int nr) {
    int c = 0;
    for (; c + 16 <= N; c += 16) {
        __m512 r[16];
        for (int i = nr; i < 16; i++) r[i] = _mm512_setzero_ps();
        for (int i = 0; i < nr; i++) {
            const double* p = src + i * ld + c;
            __m256 lo = _mm512_cvtpd_ps(_mm512_loadu_pd(p));
            __m256 hi = _mm512_cvtpd_ps(_mm512_loadu_pd(p + 8));
            r[i] = _mm512_insertf32x8(_mm512_castps256_ps512(lo), hi, 1);
        }
        tr16(r);
        for (int i = 0; i < 16; i++) _mm512_store_ps(T + (c + i) * 16, r[i]);
    }
    for (; c < N; c++) for (int i = 0; i < 16; i++) T[c * 16 + i] = i < nr ? (float)src[i * ld + c] : 0.0f;
}
static void load_T_f(const float* src, long ld, float* T) {
