        #pragma omp for schedule(static)
        for (int b = 0; b < NB; b++) {
            int k0 = b * VL;
            load_T_f(CT + (long)k0 * LD, LD, (float*)w->T);
            do_block(w, Y + k0, NTSTORE);
        }
    }
}

