static void row_group(const double *restrict x, int g, int gnext, line_t *restrict zin, line_t *restrict T, line_t *restrict Z) {
  /* load 16 rows (lanes: 0..7 re, 8..15 im) in GT order, Makhoul permuted, signed */
  {
    const double *rp[16];
    float rsa[8], rsb[8];
    for (int l = 0; l < 16; l++) {
      int i = 16*g + l;
      float s = 0.f; const double *p = x;
      if (i < N) { p = x + (size_t)g_rsrc[i] * N; s = g_rsgn[i]; }
      rp[l] = p;
      if (l < 8) rsa[l] = s; else rsb[l-8] = s;
    }
    v8f sa, sb;
    memcpy(&sa, rsa, 32); memcpy(&sb, rsb, 32);
    int c = 0;
    for (; c + 8 <= N; c += 8) {
      __m256 a[8], b[8];
#ifdef NTA_X
      if ((c & 7) == 0) for (int l = 0; l < 16; l++) _mm_prefetch((const char*)(rp[l] + c + PF_DIST), _MM_HINT_NTA);
#endif
      for (int l = 0; l < 8; l++) {
        a[l] = _mm256_insertf128_ps(_mm256_castps128_ps256(_mm256_cvtpd_ps(_mm256_loadu_pd(rp[l] + c))),
                                    _mm256_cvtpd_ps(_mm256_loadu_pd(rp[l] + c + 4)), 1);
        b[l] = _mm256_insertf128_ps(_mm256_castps128_ps256(_mm256_cvtpd_ps(_mm256_loadu_pd(rp[l+8] + c))),
                                    _mm256_cvtpd_ps(_mm256_loadu_pd(rp[l+8] + c + 4)), 1);
      }
      tr8(a); tr8(b);
      for (int t = 0; t < 8; t++) {
        line_t *o = zin + g_cdst[c + t];
        float s = g_csgn[c + t];
        o->re = (v8f)a[t] * (sa * s); o->im = (v8f)b[t] * (sb * s);
      }
    }
    for (; c < N; c++) {
      line_t *o = zin + g_cdst[c];
      float s = g_csgn[c];
      float *re = (float*)&o->re, *im = (float*)&o->im;
      for (int l = 0; l < 8; l++) { re[l] = (float)rp[l][c] * rsa[l] * s; im[l] = (float)rp[l+8][c] * rsb[l] * s; }
    }
  }
  pf_t pf; pf.nrows = 0; pf.r = 0; pf.off = 0;
  if (gnext >= 0) {
    int nr = 0;
    for (int l = 0; l < 16; l++) { int i = 16*gnext + l; if (i < N) pf.p[nr++] = (const char*)(x + (size_t)g_rsrc[i] * N); }
    pf.nrows = nr; pf.nlines = (N * 8) / 64 + 2;
  }
  fft2303(zin, T, Z, g_kmap, &pf, (pf.nrows * pf.nlines) / 96 + 1);
  /* Hermitian split (times 2) and write W[kg][rpos[i]] */
  for (int kg = 0; kg < NG; kg++) {
    __m256 Ar[8], Ai[8], Br[8], Bi[8];
    for (int kk = 0; kk < 8; kk++) {
      int k = 8*kg + kk; int m = k ? N - k : 0;
      v8f zr = Z[k].re, zi = Z[k].im, mr = Z[m].re, mi = Z[m].im;
      Ar[kk] = (__m256)(zr + mr); Ai[kk] = (__m256)(zi - mi);
      Br[kk] = (__m256)(zi + mi); Bi[kk] = (__m256)(mr - zr);
    }
    tr8(Ar); tr8(Ai); tr8(Br); tr8(Bi);
    line_t *Wg = g_W + (size_t)kg * N;
    for (int l = 0; l < 8; l++) {
      int i = 16*g + l;
      line_t *o = Wg + g_rpos[i];
#ifdef NT_W
      _mm256_stream_ps((float*)&o->re, Ar[l]); _mm256_stream_ps((float*)&o->im, Ai[l]);
#else
      o->re = (v8f)Ar[l]; o->im = (v8f)Ai[l];
#endif
      int i2 = i + 8;
      if (i2 < N) { line_t *o2 = Wg + g_rpos[i2];
#ifdef NT_W
      _mm256_stream_ps((float*)&o2->re, Br[l]); _mm256_stream_ps((float*)&o2->im, Bi[l]);
#else
      o2->re = (v8f)Br[l]; o2->im = (v8f)Bi[l];
#endif
      }
    }
  }
}

static void col_group(int kg, int kgnext, float *restrict Yt, int ld, line_t *restrict T, line_t *restrict Z) {
  const line_t *in = g_W + (size_t)kg * N;
  pf_t pf; pf.nrows = 0; pf.r = 0; pf.off = 0;
  if (kgnext >= 0) { pf.p[0] = (const char*)(g_W + (size_t)kgnext * N); pf.nrows = 1; pf.nlines = N; }
  fft2303(in, T, Z, g_kmap, &pf, N / 96 + 1);
  v8f w2r = *(const v8f*)(g_w2r + 8*kg), w2i = *(const v8f*)(g_w2i + 8*kg);
  line_t *S = T; /* S[k1].re = lo, S[k1].im = hi */
  for (int k1 = 0; k1 <= N/2; k1++) {
    int m = k1 ? N - k1 : 0;
    v8f ar = Z[k1].re, ai = Z[k1].im, br = Z[m].re, bi = Z[m].im;
    v8f pr = w2r*ar - w2i*ai, pi = w2r*ai + w2i*ar;
    v8f ur = w2r*br - w2i*bi, ui = w2r*bi + w2i*br;
    v8f Sr = pr + ur, Si = pi - ui, Dr = pr - ur, Di = pi + ui;
    float c1 = g_w1r[k1], s1 = g_w1i[k1];
    float c2 = g_w1r[m], s2 = g_w1i[m];
    /* m first so that k1 == m (k1 = 0) ends with the k1 formula (identical anyway) */
    S[m].re = c2*Sr + s2*Si;
    S[m].im = s2*Dr - c2*Di;
    S[k1].re = c1*Sr - s1*Si;
    S[k1].im = -(c1*Di + s1*Dr);
  }
  /* write: Yt[N-1-kc][N-1-k1] = lo ; Yt[kc-1][N-1-k1] = hi  (kc = 8kg + lane) */
  /* scalar head: k1 = 0..14 -> columns N-1 .. N-15 */
  for (int k1 = 0; k1 < 15; k1++) {
    float *lo = (float*)&S[k1].re, *hi = (float*)&S[k1].im;
    for (int l = 0; l < 8; l++) {
      int kc = 8*kg + l;
      Yt[(size_t)(N-1-kc)*ld + (N-1-k1)] = lo[l];
      if (kc >= 1) Yt[(size_t)(kc-1)*ld + (N-1-k1)] = hi[l];
    }
  }
  const __m256i rev = _mm256_setr_epi32(7,6,5,4,3,2,1,0);
  for (int k1 = 15; k1 + 16 <= N; k1 += 16) {
    __m256 loa[8], lob[8], hia[8], hib[8];
    for (int t = 0; t < 8; t++) {
      loa[t] = (__m256)S[k1 + t].re; hia[t] = (__m256)S[k1 + t].im;
      lob[t] = (__m256)S[k1 + 8 + t].re; hib[t] = (__m256)S[k1 + 8 + t].im;
    }
    tr8(loa); tr8(lob); tr8(hia); tr8(hib);
    int col = N - 16 - k1; /* holds k1+15 at col, ..., k1 at col+15 ; 64B aligned when ld%16==0 */
    for (int l = 0; l < 8; l++) {
      int kc = 8*kg + l;
      float *p = Yt + (size_t)(N-1-kc)*ld + col;
#ifdef NT_Y
      _mm256_stream_ps(p, _mm256_permutevar8x32_ps(lob[l], rev));
      _mm256_stream_ps(p + 8, _mm256_permutevar8x32_ps(loa[l], rev));
#else
      _mm256_storeu_ps(p, _mm256_permutevar8x32_ps(lob[l], rev));
      _mm256_storeu_ps(p + 8, _mm256_permutevar8x32_ps(loa[l], rev));
#endif
      if (kc >= 1) {
        float *q = Yt + (size_t)(kc-1)*ld + col;
#ifdef NT_Y
        _mm256_stream_ps(q, _mm256_permutevar8x32_ps(hib[l], rev));
        _mm256_stream_ps(q + 8, _mm256_permutevar8x32_ps(hia[l], rev));
#else
        _mm256_storeu_ps(q, _mm256_permutevar8x32_ps(hib[l], rev));
        _mm256_storeu_ps(q + 8, _mm256_permutevar8x32_ps(hia[l], rev));
#endif
      }
    }
  }
}

static int g_ctr[2];
void dst_run(const double *x, float *Yt, int ld) {
