def _tables():
    N = _N
    H = N // 2 + 1
    inv47 = pow(47, -1, 49)
    inv49 = pow(49, -1, 47)
    n_all = np.arange(N)

    def gtpos(n):
        a = (n * inv47) % 49
        b = (n * inv49) % 47
        return b * 49 + a

    c = np.arange(N)
    n_of_c = np.where(c % 2 == 0, c // 2, N - 1 - (c - 1) // 2)
    cdst = gtpos(n_of_c).astype(np.int32)
    csgn = np.where(c % 2 == 0, 1.0, -1.0).astype(np.float32)
    h = (N + 1) // 2
    i = n_all
    rsrc = np.where(i < h, 2 * i, 2 * (N - 1 - i) + 1).astype(np.int32)
    rsgn = np.where(i < h, 1.0, -1.0).astype(np.float32)
    rpos = gtpos(i).astype(np.int32)
    k1 = np.arange(49)[:, None]
    k2 = np.arange(47)[None, :]
    kmap = ((47 * inv47 * k1 + 49 * inv49 * k2) % N).astype(np.int32)
    kk1 = np.arange(N)
    kk2 = np.arange(H)
    w1r = np.cos(np.pi * kk1 / (2 * N)).astype(np.float32)
    w1i = (-np.sin(np.pi * kk1 / (2 * N))).astype(np.float32)
    w2r = np.cos(np.pi * kk2 / (2 * N)).astype(np.float32)
    w2i = (-np.sin(np.pi * kk2 / (2 * N))).astype(np.float32)
    return [np.ascontiguousarray(a) for a in (cdst, csgn, rsrc, rsgn, rpos, kmap, w1r, w1i, w2r, w2i)]


