Q = H1 * H2; L = 4 * Q; NP = 2304

C_SRC = r"""
#include <string.h>
#include <stdlib.h>
#include <omp.h>
#define N 2303
#define NP 2304
#define CS ((L+1)*16)
#include <immintrin.h>
#define H1 24
#define H2 25
#define Q (H1*H2)
#define L (4*Q)
#define V 16
#ifndef PF1
#define PF1 0
#endif
#ifndef PF2
#define PF2 0
#endif
typedef struct { const char *rows[16]; int lpr, nrows, r, l, per; } pfs_t;
static inline void pf_step(pfs_t *s) {
  int n = s->per;
  while (n-- > 0 && s->r < s->nrows) {
    _mm_prefetch(s->rows[s->r] + (size_t)s->l*64, _MM_HINT_T1);
    if (++s->l == s->lpr) { s->l = 0; s->r++; }
  }
}
static inline void apply_dim(const float *restrict M, const int m, const float *restrict in, float *restrict out, const int sk, const int so, const int no, pfs_t *pf) {
  for (int o = 0; o < no; o++) {
    pf_step(pf);
    const float *ip = in + o*so;
