        _mm512_store_ps(op + (i0+4)*sk, a4); _mm512_store_ps(op + (i0+5)*sk, a5);
        _mm512_store_ps(op + (i0+6)*sk, a6); _mm512_store_ps(op + (i0+7)*sk, a7);
      }
      {
        __m512 a0 = _mm512_setzero_ps(), a1 = a0, a2 = a0, a3 = a0, a4 = a0, a5 = a0, a6 = a0, a7 = a0, a8 = a0;
        const float *Mr = M + 16*m;
        for (int k = 0; k < m; k++) {
          __m512 x = _mm512_load_ps(ip + k*sk);
          a0 = _mm512_fmadd_ps(_mm512_set1_ps(Mr[k]), x, a0);
          a1 = _mm512_fmadd_ps(_mm512_set1_ps(Mr[m+k]), x, a1);
          a2 = _mm512_fmadd_ps(_mm512_set1_ps(Mr[2*m+k]), x, a2);
          a3 = _mm512_fmadd_ps(_mm512_set1_ps(Mr[3*m+k]), x, a3);
          a4 = _mm512_fmadd_ps(_mm512_set1_ps(Mr[4*m+k]), x, a4);
          a5 = _mm512_fmadd_ps(_mm512_set1_ps(Mr[5*m+k]), x, a5);
          a6 = _mm512_fmadd_ps(_mm512_set1_ps(Mr[6*m+k]), x, a6);
          a7 = _mm512_fmadd_ps(_mm512_set1_ps(Mr[7*m+k]), x, a7);
          a8 = _mm512_fmadd_ps(_mm512_set1_ps(Mr[8*m+k]), x, a8);
