        _mm512_store_ps(op + 16*sk, a0); _mm512_store_ps(op + 17*sk, a1);
        _mm512_store_ps(op + 18*sk, a2); _mm512_store_ps(op + 19*sk, a3);
        _mm512_store_ps(op + 20*sk, a4); _mm512_store_ps(op + 21*sk, a5);
        _mm512_store_ps(op + 22*sk, a6); _mm512_store_ps(op + 23*sk, a7);
        _mm512_store_ps(op + 24*sk, a8);
      }
      continue;
    }
    for (; i + 8 <= m; i += 8) {
      __m512 a0 = _mm512_setzero_ps(), a1 = a0, a2 = a0, a3 = a0, a4 = a0, a5 = a0, a6 = a0, a7 = a0;
      const float *Mr = M + i*m;
      for (int k = 0; k < m; k++) {
