      _mm512_store_ps(op + (i+2)*sk, a2); _mm512_store_ps(op + (i+3)*sk, a3);
      _mm512_store_ps(op + (i+4)*sk, a4); _mm512_store_ps(op + (i+5)*sk, a5);
      _mm512_store_ps(op + (i+6)*sk, a6); _mm512_store_ps(op + (i+7)*sk, a7);
