static inline void transform(float *restrict buf, float *restrict tmp, const float *restrict A, const float *restrict B, pfs_t *pf) {
  for (int qd = 0; qd < 4; qd++) {
    int h1 = qd >> 1, h2 = qd & 1;
    float *blk = buf + qd*Q*V;
    apply_dim(A + h1*H1*H1, H1, blk, tmp, H2*V, V, H2, pf);
    apply_dim(B + h2*H2*H2, H2, tmp, blk, V, H2*V, H1, pf);
  }
}

static inline void transpose16(__m512 *r) {
  __m512 t[16];
  for (int i = 0; i < 8; i++) { t[2*i] = _mm512_unpacklo_ps(r[2*i], r[2*i+1]); t[2*i+1] = _mm512_unpackhi_ps(r[2*i], r[2*i+1]); }
  for (int i = 0; i < 4; i++) {
    __m512d a = _mm512_castps_pd(t[4*i]), b = _mm512_castps_pd(t[4*i+1]), c = _mm512_castps_pd(t[4*i+2]), d = _mm512_castps_pd(t[4*i+3]);
    r[4*i+0] = _mm512_castpd_ps(_mm512_unpacklo_pd(a, c)); r[4*i+1] = _mm512_castpd_ps(_mm512_unpackhi_pd(a, c));
    r[4*i+2] = _mm512_castpd_ps(_mm512_unpacklo_pd(b, d)); r[4*i+3] = _mm512_castpd_ps(_mm512_unpackhi_pd(b, d));
  }
  for (int h = 0; h < 2; h++) for (int j = 0; j < 4; j++) {
    t[8*h+j]   = _mm512_shuffle_f32x4(r[8*h+j], r[8*h+4+j], 0x88);
    t[8*h+4+j] = _mm512_shuffle_f32x4(r[8*h+j], r[8*h+4+j], 0xdd);
  }
  for (int j = 0; j < 8; j++) {
    r[j]   = _mm512_shuffle_f32x4(t[j], t[8+j], 0x88);
    r[8+j] = _mm512_shuffle_f32x4(t[j], t[8+j], 0xdd);
  }
}

static inline int pidx(int h1, int h2, int j1, int j2) { return ((h1*2+h2)*H1 + j1)*H2 + j2; }

void run(const double *restrict X, float *restrict T1, float *restrict Y,
         const int *restrict gsrc, const float *restrict gcoef, const int *restrict prow,
         const float *restrict colsign, const int *restrict oidx, const float *restrict ocoef,
         const float *restrict A, const float *restrict B, int nthreads, double *restrict tm)
{
  tm[0] = omp_get_wtime();
  #pragma omp parallel num_threads(nthreads)
  {
    float *t2 = (float*)aligned_alloc(64, sizeof(float)*N*V);
    float *buf = (float*)aligned_alloc(64, sizeof(float)*L*V);
    float *tmp = (float*)aligned_alloc(64, sizeof(float)*Q*V);
    memset(buf, 0, sizeof(float)*L*V);
    double ts[4] = {0,0,0,0};
    const int NTH = omp_get_num_threads();
    pfs_t pf;
    #pragma omp for schedule(dynamic,1)
    for (int g = 0; g < 150; g++) {
      double q0 = omp_get_wtime();
      const double *xr[16]; float sc[16];
      for (int gi = 0; gi < 4; gi++) for (int i = 0; i < 4; i++) {
        int rg = 4*g + gi;
        xr[gi*4+i] = X + (size_t)gsrc[rg*4+i]*N; sc[gi*4+i] = gcoef[rg*4+i];
      }
      for (int jb = 0; jb < N/16; jb++) {
        const int j0 = jb*16;
        const __m512 csv = _mm512_loadu_ps(colsign + j0);
        __m512 r[16];
        for (int gi = 0; gi < 4; gi++) {
          __m512 x[4];
          for (int i = 0; i < 4; i++) {
            const double *pp = xr[gi*4+i] + j0;
            __m256 lo = _mm512_cvtpd_ps(_mm512_loadu_pd(pp)), hi = _mm512_cvtpd_ps(_mm512_loadu_pd(pp+8));
            x[i] = _mm512_mul_ps(_mm512_set1_ps(sc[gi*4+i]), _mm512_insertf32x8(_mm512_castps256_ps512(lo), hi, 1));
          }
          __m512 p01 = _mm512_add_ps(x[0], x[1]), m01 = _mm512_sub_ps(x[0], x[1]);
          __m512 p23 = _mm512_add_ps(x[2], x[3]), m23 = _mm512_sub_ps(x[2], x[3]);
          r[gi*4+0] = _mm512_mul_ps(csv, _mm512_add_ps(p01, p23));
          r[gi*4+1] = _mm512_mul_ps(csv, _mm512_add_ps(m01, m23));
          r[gi*4+2] = _mm512_mul_ps(csv, _mm512_sub_ps(p01, p23));
          r[gi*4+3] = _mm512_mul_ps(csv, _mm512_sub_ps(m01, m23));
        }
        transpose16(r);
        for (int jj = 0; jj < 16; jj++) _mm512_store_ps(t2 + (j0+jj)*V, r[jj]);
      }
      for (int j = (N/16)*16; j < N; j++) {
        const float cs = colsign[j];
        float *o = t2 + j*V;
        for (int gi = 0; gi < 4; gi++) {
          float x0 = sc[gi*4+0]*(float)xr[gi*4+0][j];
          float x1 = sc[gi*4+1]*(float)xr[gi*4+1][j];
          float x2 = sc[gi*4+2]*(float)xr[gi*4+2][j];
          float x3 = sc[gi*4+3]*(float)xr[gi*4+3][j];
          float p01 = x0+x1, m01 = x0-x1, p23 = x2+x3, m23 = x2-x3;
          o[gi*4+0] = cs*(p01+p23); o[gi*4+1] = cs*(m01+m23);
          o[gi*4+2] = cs*(p01-p23); o[gi*4+3] = cs*(m01-m23);
        }
      }
      double q1 = omp_get_wtime();
      const __m512 zero = _mm512_setzero_ps();
      for (int gc = 0; gc < Q; gc++) {
        const int uc = gc / H2, ud = gc % H2;
        __m512 y0 = _mm512_load_ps(t2 + gsrc[gc*4+0]*V);
        __m512 y1 = ud ? _mm512_load_ps(t2 + gsrc[gc*4+1]*V) : zero;
        __m512 y2 = uc ? _mm512_load_ps(t2 + gsrc[gc*4+2]*V) : zero;
        __m512 y3 = (uc && ud) ? _mm512_load_ps(t2 + gsrc[gc*4+3]*V) : zero;
        __m512 p01 = _mm512_add_ps(y0, y1), m01 = _mm512_sub_ps(y0, y1);
        __m512 p23 = _mm512_add_ps(y2, y3), m23 = _mm512_sub_ps(y2, y3);
        _mm512_store_ps(buf + pidx(0,0,uc,ud)*V, _mm512_add_ps(p01, p23));
        if (ud) _mm512_store_ps(buf + pidx(0,1,uc,ud-1)*V, _mm512_add_ps(m01, m23));
        if (uc) _mm512_store_ps(buf + pidx(1,0,uc-1,ud)*V, _mm512_sub_ps(p01, p23));
        if (uc && ud) _mm512_store_ps(buf + pidx(1,1,uc-1,ud-1)*V, _mm512_sub_ps(m01, m23));
      }
      double q2 = omp_get_wtime();
      {
        const int gn = g + NTH;
        pf.lpr = (N*8 + 63)/64; pf.r = 0; pf.l = 0; pf.per = PF1;
        pf.nrows = (gn < 150) ? 16 : 0;
        if (gn < 150) for (int gi = 0; gi < 4; gi++) for (int i = 0; i < 4; i++)
          pf.rows[gi*4+i] = (const char*)(X + (size_t)gsrc[(4*gn+gi)*4+i]*N);
      }
      transform(buf, tmp, A, B, &pf);
      double q3 = omp_get_wtime();
      float *orow[16];
      for (int l = 0; l < 16; l++) orow[l] = T1 + (size_t)prow[g*16+l]*V;
      for (int kb = 0; kb < NP/16; kb++) {
        __m512 r[16];
        for (int kk = 0; kk < 16; kk++) {
          const int k = kb*16 + kk;
          r[kk] = _mm512_fmadd_ps(_mm512_set1_ps(ocoef[2*k]), _mm512_load_ps(buf + oidx[2*k]*V),
                     _mm512_mul_ps(_mm512_set1_ps(ocoef[2*k+1]), _mm512_load_ps(buf + oidx[2*k+1]*V)));
        }
        transpose16(r);
        for (int l = 0; l < 16; l++) _mm512_store_ps(orow[l] + (size_t)kb*CS, r[l]);
      }
      double q4 = omp_get_wtime();
      ts[0] += q1-q0; ts[1] += q2-q1; ts[2] += q3-q2; ts[3] += q4-q3;
    }
    if (omp_get_thread_num() == 0) { tm[3] = ts[0]; tm[4] = ts[1]; tm[5] = ts[2]; tm[6] = ts[3]; }
    #pragma omp master
    tm[1] = omp_get_wtime();
    double us[3] = {0,0,0};
    #pragma omp for schedule(dynamic,1)
    for (int ci = 0; ci < NP/V; ci++) {
      double q0 = omp_get_wtime();
      const int c0 = ci*V;
      for (int p = 0; p < L; p++)
        _mm512_store_ps(buf + p*V, _mm512_load_ps(T1 + (size_t)ci*CS + p*V));
      double q1 = omp_get_wtime();
      {
        const int cn = ci + NTH;
        pf.lpr = (L*V*4)/64; pf.r = 0; pf.l = 0; pf.per = PF2;
        pf.nrows = (cn < NP/V) ? 1 : 0;
        pf.rows[0] = (const char*)(T1 + (size_t)cn*CS);
      }
      transform(buf, tmp, A, B, &pf);
      double q2 = omp_get_wtime();
      for (int k = 0; k < N; k++) {
        __m512 v = _mm512_fmadd_ps(_mm512_set1_ps(ocoef[2*k]), _mm512_load_ps(buf + oidx[2*k]*V),
                     _mm512_mul_ps(_mm512_set1_ps(ocoef[2*k+1]), _mm512_load_ps(buf + oidx[2*k+1]*V)));
        _mm512_storeu_ps(Y + (size_t)k*NP + c0, v);
      }
      double q3 = omp_get_wtime();
      us[0] += q1-q0; us[1] += q2-q1; us[2] += q3-q2;
    }

    if (omp_get_thread_num() == 0) { tm[7] = us[0]; tm[8] = us[1]; tm[9] = us[2]; }
    free(t2); free(buf); free(tmp);
  }
  tm[2] = omp_get_wtime();
}
"""

def _small_mats(p, H):
    Mc = np.zeros((H, H)); Ms = np.zeros((H, H))
    for t in range(H):
        for j in range(H):
            if t <= (p-1)//2 and j <= (p-1)//2:
                Mc[t, j] = np.cos(2*np.pi*j*t/p)
            if t <= (p-1)//2 - 1 and j <= (p-1)//2 - 1:
                Ms[t, j] = np.sin(2*np.pi*(j+1)*(t+1)/p)
    return np.stack([Mc, Ms])

def _pidx(h1, h2, j1, j2):
    return ((h1*2+h2)*H1 + j1)*H2 + j2

def _tables():
    a_ = pow(N, -1, 4); b_ = pow(4, -1, N)
    m = np.array([(r + N*((1 - r) * a_ % 4)) % (4*N) for r in range(N)])
    n_of_r = np.where(m < 2*N, (m-1)//2, (4*N - m - 1)//2)
    def nr(r1, r2):
        return int(n_of_r[(P2*(r1 % P1) + P1*(r2 % P2)) % N])
    sgn = (1 - 2*(np.arange(N) % 2)).astype(np.float64)
    gsrc = np.zeros((Q, 4), np.int32); gcoef = np.zeros((Q, 4), np.float32)
    prow = np.full((Q, 4), L, np.int32)
    for u1 in range(H1):
        for u2 in range(H2):
            g = u1*H2 + u2
            src = [nr(u1, u2), nr(u1, -u2), nr(-u1, u2), nr(-u1, -u2)]
            gsrc[g] = src
            f = [1, 0 if u2 == 0 else 1, 0 if u1 == 0 else 1, 0 if (u1 == 0 or u2 == 0) else 1]
            gcoef[g] = [sgn[src[i]]*f[i] for i in range(4)]
            for c in range(4):
                ha, hb = c >> 1, c & 1
                if (ha == 1 and u1 == 0) or (hb == 1 and u2 == 0):
                    continue
                prow[g, c] = _pidx(ha, hb, u1-ha, u2-hb)
    oidx = np.zeros((N, 2), np.int32); ocoef = np.zeros((N, 2), np.float32)
    for k in range(N):
        kk = N-1-k
        t = (b_*kk) % N; phi = (a_*kk) % 4
        t1 = t % P1; t2 = t % P2
        u1 = min(t1, P1-t1); s1 = 1 if t1 <= (P1-1)//2 else -1
        u2 = min(t2, P2-t2); s2 = 1 if t2 <= (P2-1)//2 else -1
        cphi = [1, 0, -1, 0][phi]; sphi = [0, 1, 0, -1][phi]
        if cphi != 0:
            oidx[k, 0] = _pidx(0, 0, u1, u2); ocoef[k, 0] = cphi
            if u1 >= 1 and u2 >= 1:
                oidx[k, 1] = _pidx(1, 1, u1-1, u2-1); ocoef[k, 1] = -cphi*s1*s2
        else:
            if u1 >= 1:
                oidx[k, 0] = _pidx(1, 0, u1-1, u2); ocoef[k, 0] = -sphi*s1
            if u2 >= 1:
                oidx[k, 1] = _pidx(0, 1, u1, u2-1); ocoef[k, 1] = -sphi*s2
    ocoef *= 2.0
    oidx = np.concatenate([oidx, np.zeros((NP-N, 2), np.int32)]); ocoef = np.concatenate([ocoef, np.zeros((NP-N, 2), np.float32)])
    colsign = np.concatenate([sgn, np.zeros(NP-N)]).astype(np.float32)
    A = _small_mats(P1, H1).astype(np.float32)
    B = _small_mats(P2, H2).astype(np.float32)
    return gsrc, gcoef, prow, colsign, oidx, ocoef, A, B

def _build():
    h = hashlib.md5(C_SRC.encode()).hexdigest()[:12]
    d = tempfile.gettempdir()
    so = os.path.join(d, f"dst2_{h}.so")
    if not os.path.exists(so):
        src = os.path.join(d, f"dst2_{h}.c")
        with open(src, "w") as f:
            f.write(C_SRC)
        tmpso = so + f".{os.getpid()}.tmp"
        subprocess.check_call(["gcc", "-O3", "-march=native", "-ffast-math", "-fopenmp", "-shared", "-fPIC",
                               "-o", tmpso, src])
        os.replace(tmpso, so)
    lib = ctypes.CDLL(so)
    lib.run.restype = None
    return lib

class Solver:
    def __init__(self):
        self.fallback = False
        try:
            flags = open('/proc/cpuinfo').read()
            if 'avx512f' not in flags:
                raise RuntimeError('no avx512')
            self.lib = _build()
        except Exception:
            self.fallback = True
            return
        tabs = _tables()
        self.tabs = [np.ascontiguousarray(t) for t in tabs]
        raw = np.zeros((NP // 16) * (L + 1) * 16 + 64, np.float32)
        off = (-raw.ctypes.data % 64) // 4
        self._T1raw = raw
        self.T1 = raw[off:off + (NP // 16) * (L + 1) * 16]
        self.nthreads = len(os.sched_getaffinity(0))
        self.tm = np.zeros(16)
        self._ptrs = [t.ctypes.data for t in self.tabs]
        self.solve(np.random.rand(N, N))

    def solve(self, problem, **kwargs):
        X = np.asarray(problem)
        if self.fallback or X.shape != (N, N):
            import scipy.fft
            return scipy.fft.dstn(X.astype(np.float64), type=2, workers=-1)
        X = np.ascontiguousarray(X, dtype=np.float64)
        raw = np.empty(N * NP + 16, np.float32)
