/* post-processing; output for frequency row j goes to rowptr(j) = base + j*rs (rs in floats) */
static inline __attribute__((always_inline)) void post(cv* buf, float* base, size_t rs_lo, size_t tile_mode, int nt) {
    /* tile_mode: if nonzero, row j at base + (j/LB)*tile_mode + (j%LB)*LB ; else base + j*rs_lo */
#define ROWP(j) (tile_mode ? base + (size_t)((j) / LB) * tile_mode + (size_t)((j) % LB) * LB : base + (size_t)(j) * rs_lo)
    {
        cv z = buf[qpos[0]];
        float* o = ROWP(NN - 1);
        vstore(o, z.re * 2.0f, nt); vstore(o + VL, z.im * 2.0f, nt);
    }
    for (int k = 1; k <= (NN - 1) / 2; k++) {
        cv zk = buf[qpos[k]], zm = buf[qpos[NN - k]];
        vf Pr = zk.re + zm.re, Pi = zk.im - zm.im;
        vf Qr = zk.im + zm.im, Qi = zm.re - zk.re;
        float tc = twc[k], ts = tws[k];
        float* o1 = ROWP(NN - 1 - k);
        float* o2 = ROWP(k - 1);
        vstore(o1, tc * Pr + ts * Pi, nt); vstore(o1 + VL, tc * Qr + ts * Qi, nt);
        vstore(o2, ts * Pr - tc * Pi, nt); vstore(o2 + VL, ts * Qr - tc * Qi, nt);
    }
#undef ROWP
}

/* pass 1 (row mode): block b = rows i of X; transform along columns n; output tile (k/LB, b) row k%LB */
#ifndef PFC
#define PFC 64
#endif
static void block_pass1(const double* X, float* Zt, int b, cv* buf, int bnext) {
    int line0 = b * LB; int nl = NN - line0; if (nl > LB) nl = LB;
#ifdef HAVE_TR16
    for (int c0 = 0; c0 < NN; c0 += 16) {
        int lim = NN - c0; if (lim > 16) lim = 16;
        __mmask8 mlo = 0xFF, mhi = 0xFF;
        if (lim < 16) {
            mlo = lim >= 8 ? 0xFF : (__mmask8)((1u << lim) - 1);
            mhi = lim > 8 ? (__mmask8)((1u << (lim - 8)) - 1) : 0;
        }
        for (int rr = 0; rr < LB; rr += 16) {
            __m512 r[16];
            for (int i = 0; i < 16; i++) {
                int row = rr + i;
                if (row < nl) {
                    const double* p = X + (size_t)(line0 + row) * NN + c0;
                    __m512d lo, hi;
                    if (lim == 16) {
#if PFC > 0
                        __builtin_prefetch(p + PFC, 0, 3); __builtin_prefetch(p + PFC + 8, 0, 3);
#endif
                        lo = _mm512_loadu_pd(p); hi = _mm512_loadu_pd(p + 8);
                    } else {
                        lo = _mm512_maskz_loadu_pd(mlo, p); hi = _mm512_maskz_loadu_pd(mhi, p + 8);
                    }
                    __m256 flo = _mm512_cvtpd_ps(lo), fhi = _mm512_cvtpd_ps(hi);
                    r[i] = _mm512_castpd_ps(_mm512_insertf64x4(_mm512_castpd256_pd512(_mm256_castps_pd(flo)), _mm256_castps_pd(fhi), 1));
                } else {
                    r[i] = _mm512_setzero_ps();
                }
            }
            tr16(r);
            if (rr == 0) {
                for (int i = 0; i < lim; i++) buf[pos_in[c0 + i]].re = (vf)r[i] * sg_in[c0 + i];
            } else {
                for (int i = 0; i < lim; i++) buf[pos_in[c0 + i]].im = (vf)r[i] * sg_in[c0 + i];
            }
        }
    }
#else
    float* bf = (float*)buf;
    for (int l = 0; l < LB; l++) {
        if (l < nl) {
            const double* r = X + (size_t)(line0 + l) * NN;
            for (int n = 0; n < NN; n++) bf[pos_in[n] * LB + l] = (float)r[n] * sg_in[n];
        } else {
            for (int n = 0; n < NN; n++) bf[n * LB + l] = 0.0f;
        }
    }
#endif
    pfd_t d = {0};
    if (bnext >= 0 && bnext < NB) {
        size_t r0 = (size_t)bnext * LB; size_t nr = NN - r0; if (nr > LB) nr = LB;
        d.base = (const char*)(X + r0 * NN); d.rstride = 4096; d.nrows = (int)((nr * NN * 8) / 4096); d.nlines = 64;
    }
    fft_all(buf, PF1 ? &d : 0);
    post(buf, Zt + (size_t)b * LB * LB, 0, (size_t)NB * LB * LB, PASS1_NT);
}

/* pass 2: Zt tiles, block b = tile row (rows j of Z); output W rows k (stride WS), cols b*LB.. */
static void block_pass2(const float* Zt, float* W, int b, cv* buf, int bnext) {
    const float* trow = Zt + (size_t)b * NB * LB * LB;
#ifdef HAVE_TR16
    for (int tc = 0; tc < NB; tc++) {
        const float* T = trow + (size_t)tc * LB * LB;
        for (int cc = 0; cc < LB; cc += 16) {
            int n0 = tc * LB + cc;
            if (n0 >= NN) break;
            for (int rr = 0; rr < LB; rr += 16) {
                __m512 r[16];
                for (int i = 0; i < 16; i++) r[i] = _mm512_load_ps(T + (rr + i) * LB + cc);
                tr16(r);
                int lim = NN - n0; if (lim > 16) lim = 16;
                if (rr == 0) {
                    for (int i = 0; i < lim; i++) buf[pos_in[n0 + i]].re = (vf)r[i] * sg_in[n0 + i];
                } else {
                    for (int i = 0; i < lim; i++) buf[pos_in[n0 + i]].im = (vf)r[i] * sg_in[n0 + i];
                }
            }
        }
    }
#else
    float* bf = (float*)buf;
    for (int tc = 0; tc < NB; tc++) {
        const float* T = trow + (size_t)tc * LB * LB;
        for (int r = 0; r < LB; r++)
            for (int c = 0; c < LB; c++) {
                int n = tc * LB + c;
                if (n < NN) bf[pos_in[n] * LB + r] = T[r * LB + c] * sg_in[n];
            }
    }
#endif
    pfd_t d = {0};
    if (bnext >= 0 && bnext < NB) { d.base = (const char*)(Zt + (size_t)bnext * NB * LB * LB); d.rstride = 4096; d.nrows = NB * LB * LB * 4 / 4096; d.nlines = 64; }
    fft_all(buf, PF2 ? &d : 0);
    post(buf, W + (size_t)b * LB, WS, 0, PASS2_NT);
