/* post-processing; output for frequency row j goes to rowptr(j) = base + j*rs (rs in floats) */
static inline __attribute__((always_inline)) void post(cv* buf, float* base, size_t rs_lo, size_t tile_mode, int nt) {
    /* tile_mode: if nonzero, row j at base + (j/LB)*tile_mode + (j%LB)*LB ; else base + j*rs_lo */
#define ROWP(j) (tile_mode ? base + (size_t)((j) / LB) * tile_mode + (size_t)((j) % LB) * LB : base + (size_t)(j) * rs_lo)
    {
        cv z = buf[qpos[0]];
        float* o = ROWP(NN - 1);
        vstore(o, z.re * 2.0f, nt); vstore(o + VL, z.im * 2.0f, nt);
    }
    for (int k = 1; k <= (NN - 1) / 2; k++) {
        cv zk = buf[qpos[k]], zm = buf[qpos[NN - k]];
        vf Pr = zk.re + zm.re, Pi = zk.im - zm.im;
        vf Qr = zk.im + zm.im, Qi = zm.re - zk.re;
        float tc = twc[k], ts = tws[k];
        float* o1 = ROWP(NN - 1 - k);
        float* o2 = ROWP(k - 1);
        vstore(o1, tc * Pr + ts * Pi, nt); vstore(o1 + VL, tc * Qr + ts * Qi, nt);
        vstore(o2, ts * Pr - tc * Pi, nt); vstore(o2 + VL, ts * Qr - tc * Qi, nt);
    }
#undef ROWP
}

