_FLAGS = ['-O3', '-mavx512f', '-mavx512dq', '-mavx512vl', '-mavx512bw', '-mfma', '-mavx2', '-mtune=znver4', '-mprefer-vector-width=512', '-ffast-math', '-fPIC', '-shared']


def _make_tables():
    perm = np.empty(N, np.int64)
    h = (N + 1) // 2
    perm[:h] = 2 * np.arange(h)
    perm[h:] = (2 * np.arange((N - 1) // 2) + 1)[::-1]
    n1 = np.arange(N1)[:, None]
    n2 = np.arange(N2)[None, :]
    m = (N2 * n1 + N1 * n2) % N
    idx = np.ascontiguousarray(perm[m].T).astype(np.int32)
    u = pow(N2, -1, N1)
    v = pow(N1, -1, N2)
    k1 = np.arange(N1)[:, None]
    k2 = np.arange(N2)[None, :]
    K = ((N2 * u * k1 + N1 * v * k2) % N)[:24]
    o1 = (N - 1 - K).astype(np.int32)
    o2 = (K - 1).astype(np.int32)
    o2[0] = 0
    th = np.pi * K / (2 * N)
    ph = np.pi * (N - K) / (2 * N)
    cf = np.zeros((24, 49, 4), np.float64)
    cf[:, :, 0] = 2 * np.cos(th)
    cf[:, :, 1] = 2 * np.sin(th)
    cf[:, :, 2] = 2 * np.cos(ph)
    cf[:, :, 3] = -2 * np.sin(ph)
    kk = np.arange(24)[:, None]
    jj = np.arange(24)[None, :]
    C = np.cos(2 * np.pi * kk * jj / N1)
    S = np.sin(2 * np.pi * kk * (jj + 1) / N1)
    S[:, 23] = 0.0
    q = np.arange(7)[:, None]
    r = np.arange(7)[None, :]
    w = np.exp(-2j * np.pi * q * r / 49)
    tw = np.stack([w.real, w.imag], -1)
    sg = np.where(np.arange(N) % 2 == 0, 1.0, -1.0)
    f = np.float32
    return [np.ascontiguousarray(a) for a in (idx, C.astype(f), S.astype(f), tw.astype(f), o1, o2,
                                              cf.astype(f), sg.astype(f))]


def _aligned(shape, dtype=np.float32):
    n = int(np.prod(shape))
    it = np.dtype(dtype).itemsize
    buf = np.empty(n + 64 // it, dtype)
    off = (-buf.ctypes.data % 64) // it
    return buf[off:off + n].reshape(shape)


def _cpu_ok():
    try:
        with open("/proc/cpuinfo") as fh:
            for line in fh:
                if line.startswith("flags"):
                    fl = set(line.split(":", 1)[1].split())
                    return all(x in fl for x in ("avx512f", "avx512dq", "avx512vl", "avx512bw", "fma", "avx2"))
    except Exception:
        pass
    return False


def _load_lib():
    d = tempfile.mkdtemp(prefix="dst2_")
    path = os.path.join(d, "dst.so")
    try:
        with open(path, "wb") as fh:
            fh.write(zlib.decompress(base64.b64decode(_BLOB)))
        return ctypes.CDLL(path)
    except Exception:
        pass
    src = os.path.join(d, "dst.c")
    with open(src, "w") as fh:
        fh.write(_SRC)
    path2 = os.path.join(d, "dst2.so")
    subprocess.check_call(["gcc"] + _FLAGS + ["-o", path2, src, "-lpthread"],
                          stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
    return ctypes.CDLL(path2)


class Solver:
    def __init__(self):
        self.lib = None
        try:
            self.nth = len(os.sched_getaffinity(0))
        except Exception:
            self.nth = os.cpu_count() or 1
        try:
            if _cpu_ok():
                lib = _load_lib()
                P = ctypes.c_void_p
                self.tabs = _make_tables()
                lib.init_tables.argtypes = [P] * 8
                lib.init_tables.restype = None
                lib.init_tables(*[a.ctypes.data for a in self.tabs])
                lib.dst2.argtypes = [P, P, P, ctypes.c_int]
                lib.dst2.restype = None
                self.Y = _aligned((NP, NP))
                self.Y[:] = 0
                self.lib = lib
                x = np.random.rand(N, N)
                y = self._run(x)
                ref = scipy.fft.dstn(x, type=2)
                err = np.linalg.norm(y - ref) / np.linalg.norm(ref)
                if not (err < 1e-6):
                    self.lib = None
        except Exception:
            self.lib = None

    def _run(self, x):
        O = _aligned((N, NP))
        self.lib.dst2(x.ctypes.data, self.Y.ctypes.data, O.ctypes.data, self.nth)
        return O[:, :N]

    def solve(self, problem, **kwargs):
        x = problem
        if self.lib is not None and isinstance(x, np.ndarray) and x.shape == (N, N):
            if x.dtype != np.float64 or not x.flags.c_contiguous:
                x = np.ascontiguousarray(x, dtype=np.float64)
            return self._run(x)
        x = np.asarray(x, dtype=np.float32)
        return scipy.fft.dstn(x, type=2, workers=self.nth)
